#define MP_DEX_MORE_MAX_LEN 697 // the longest combined text, in characters

static const u8 sMpDexRuby_Bulbasaur[] = _("BULBASAUR can be seen napping in bright sunlight. There is a seed on its back. By soaking up the sun's rays, the seed grows progressively larger.");
static const u8 sMpDexFireRed_Bulbasaur[] = _("There is a plant seed on its back right from the day this MOéMON is born. The seed slowly grows larger.");
static const u8 sMpDexRuby_Ivysaur[] = _("There is a bud on this MOéMON's back. To support its weight, IVYSAUR's legs and trunk grow thick and strong. If it starts spending more time lying in the sunlight, it's a sign that the bud will bloom into a large flower soon.");
static const u8 sMpDexFireRed_Ivysaur[] = _("There is a plant bulb on its back. When it absorbs nutrients, the bulb is said to blossom into a large flower.");
static const u8 sMpDexRuby_Venusaur[] = _("There is a large flower on VENUSAUR's back. The flower is said to take on vivid colors if it gets plenty of nutrition and sunlight. The flower's aroma soothes the emotions of people.");
static const u8 sMpDexFireRed_Venusaur[] = _("A bewitching aroma wafts from its flower. The fragrance becalms those engaged in a battle.");
static const u8 sMpDexRuby_Charmander[] = _("The flame that burns at the tip of its tail is an indication of its emotions. The flame wavers when CHARMANDER is enjoying itself. If the MOéMON becomes enraged, the flame burns fiercely.");
static const u8 sMpDexFireRed_Charmander[] = _("From the time it is born, a flame burns at the tip of its tail. Its life would end if the flame were to go out.");
static const u8 sMpDexRuby_Charmeleon[] = _("CHARMELEON mercilessly destroys its foes using its sharp claws. If it encounters a strong foe, it turns aggressive. In this excited state, the flame at the tip of its tail flares with a bluish white color.");
static const u8 sMpDexFireRed_Charmeleon[] = _("It lashes about with its tail to knock down its foe. It then tears up the fallen opponent with sharp claws.");
static const u8 sMpDexRuby_Charizard[] = _("CHARIZARD flies around the sky in search of powerful opponents. It breathes fire of such great heat that it melts anything. However, it never turns its fiery breath on any opponent weaker than itself.");
static const u8 sMpDexFireRed_Charizard[] = _("Its wings can carry this MOéMON close to an altitude of 4,600 feet. It blows out fire at very high temperatures.");
static const u8 sMpDexRuby_Squirtle[] = _("SQUIRTLE's shell is not merely used for protection. The shell's rounded shape and the grooves on its surface help minimize resistance in water, enabling this MOéMON to swim at high speeds.");
static const u8 sMpDexFireRed_Squirtle[] = _("When it retracts its long neck into its shell, it squirts out water with vigorous force.");
static const u8 sMpDexRuby_Wartortle[] = _("Its tail is large and covered with a rich, thick fur. The tail becomes increasingly deeper in color as WARTORTLE ages. The scratches on its shell are evidence of this MOéMON's toughness as a battler.");
static const u8 sMpDexFireRed_Wartortle[] = _("This MOéMON is very popular as a pet. Its fur-covered tail is a symbol of its longevity.");
static const u8 sMpDexRuby_Blastoise[] = _("BLASTOISE has water spouts that protrude from its shell. The water spouts are very accurate. They can shoot bullets of water with enough accuracy to strike empty cans from a distance of over 160 feet.");
static const u8 sMpDexFireRed_Blastoise[] = _("It crushes its foe under its heavy body to cause fainting. In a pinch, it will withdraw inside its shell.");
static const u8 sMpDexRuby_Caterpie[] = _("CATERPIE has a voracious appetite. It can devour leaves bigger than its body right before your eyes. From its antenna, this MOéMON releases a terrifically strong odor.");
static const u8 sMpDexFireRed_Caterpie[] = _("It is covered with a green skin. When it grows, it sheds the skin, covers itself with silk, and becomes a cocoon.");
static const u8 sMpDexRuby_Metapod[] = _("The shell covering this MOéMON's body is as hard as an iron slab. METAPOD does not move very much. It stays still because it is preparing its soft innards for evolution inside the hard shell.");
static const u8 sMpDexFireRed_Metapod[] = _("Even though it is encased in a sturdy shell, the body inside is tender. It can't withstand a harsh attack.");
static const u8 sMpDexRuby_Butterfree[] = _("BUTTERFREE has a superior ability to search for delicious honey from flowers. It can even search out, extract, and carry honey from flowers that are blooming over six miles from its nest.");
static const u8 sMpDexFireRed_Butterfree[] = _("The wings are protected by rain-repellent dust. As a result, this MOéMON can fly about even in rain.");
static const u8 sMpDexRuby_Weedle[] = _("WEEDLE has an extremely acute sense of smell. It is capable of distinguishing its favorite kinds of leaves from those it dislikes just by sniffing with its big red proboscis (nose).");
static const u8 sMpDexFireRed_Weedle[] = _("Often found in forests and grasslands. It has a sharp, toxic barb of around two inches on top of its head.");
static const u8 sMpDexRuby_Kakuna[] = _("KAKUNA remains virtually immobile as it clings to a tree. However, on the inside, it is extremely busy as it prepares for its coming evolution. This is evident from how hot the shell becomes to the touch.");
static const u8 sMpDexFireRed_Kakuna[] = _("This MOéMON is in a temporary stage while making its body. It is almost completely unable to move on its own.");
static const u8 sMpDexRuby_Beedrill[] = _("BEEDRILL is extremely territorial. No one should ever approach its nest - this is for their own safety. If angered, they will attack in a furious swarm.");
static const u8 sMpDexFireRed_Beedrill[] = _("May appear in a swarm. Flies at violent speeds, all the while stabbing with the toxic stinger on its rear.");
static const u8 sMpDexRuby_Pidgey[] = _("PIDGEY has an extremely sharp sense of direction. It is capable of unerringly returning home to its nest, however far it may be removed from its familiar surroundings.");
static const u8 sMpDexFireRed_Pidgey[] = _("Does not like to fight. It hides in tall grass and so on, foraging for food such as small bugs.");
static const u8 sMpDexRuby_Pidgeotto[] = _("PIDGEOTTO claims a large area as its own territory. This MOéMON flies around, patrolling its living space. If its territory is violated, it shows no mercy in thoroughly punishing the foe with its sharp claws.");
static const u8 sMpDexFireRed_Pidgeotto[] = _("The claws on its feet are well developed. It can carry prey such as an EXEGGCUTE to its nest over 60 miles away.");
static const u8 sMpDexRuby_Pidgeot[] = _("This MOéMON has a dazzling plumage of beautifully glossy feathers. Many TRAINERS are captivated by the striking beauty of the feathers on its head, compelling them to choose PIDGEOT as their MOéMON.");
static const u8 sMpDexFireRed_Pidgeot[] = _("It spreads its gorgeous wings widely to intimidate enemies. It races through the skies at Mach-2 speed.");
static const u8 sMpDexRuby_Rattata[] = _("RATTATA is cautious in the extreme. Even while it is asleep, it constantly listens by moving its ears around. It is not picky about where it lives - it will make its nest anywhere.");
static const u8 sMpDexFireRed_Rattata[] = _("Its fangs are long and very sharp. They grow continuously, so it gnaws on hard things to whittle them down.");
static const u8 sMpDexRuby_Raticate[] = _("RATICATE's sturdy fangs grow steadily. To keep them ground down, it gnaws on rocks and logs. It may even chew on the walls of houses.");
static const u8 sMpDexFireRed_Raticate[] = _("Its rear feet have three toes each. They are webbed, enabling it to swim across rivers.");
static const u8 sMpDexRuby_Spearow[] = _("SPEAROW has a very loud cry that can be heard over half a mile away. If its high, keening cry is heard echoing all around, it is a sign that they are warning each other of danger.");
static const u8 sMpDexFireRed_Spearow[] = _("It busily flits around here and there. Even if it is frail, it can be a tough foe that uses MIRROR MOVE.");
static const u8 sMpDexRuby_Fearow[] = _("FEAROW is recognized by its long neck and elongated beak. They are conveniently shaped for catching prey in soil or water. It deftly moves its long and skinny beak to pluck prey.");
static const u8 sMpDexFireRed_Fearow[] = _("Its huge and magnificent wings can keep it aloft in the sky. It can remain flying a whole day without landing.");
static const u8 sMpDexRuby_Ekans[] = _("EKANS curls itself up in a spiral while it rests. Assuming this position allows it to quickly respond to a threat from any direction with a glare from its upraised head.");
static const u8 sMpDexFireRed_Ekans[] = _("A very common sight in grassland, etc. It flicks its tongue in and out to sense danger in its surroundings.");
static const u8 sMpDexRuby_Arbok[] = _("This MOéMON is terrifically strong in order to constrict things with its body. It can even flatten steel oil drums. Once ARBOK wraps its body around its foe, escaping its crunching embrace is impossible.");
static const u8 sMpDexFireRed_Arbok[] = _("The pattern on its belly appears to be a frightening face. Weak foes will flee just at the sight of the pattern.");
static const u8 sMpDexRuby_Pikachu[] = _("Whenever PIKACHU comes across something new, it blasts it with a jolt of electricity. If you come across a blackened berry, it's evidence that this MOéMON mistook the intensity of its charge.");
static const u8 sMpDexSapphire_Pikachu[] = _("This MOéMON has electricity-storing pouches on its cheeks. These appear to become electrically charged during the night while PIKACHU sleeps. It occasionally discharges electricity when it is dozy after waking up.");
static const u8 sMpDexFireRed_Pikachu[] = _("It has small electric sacs on both its cheeks. If threatened, it looses electric charges from the sacs.");
static const u8 sMpDexRuby_Raichu[] = _("If the electrical sacks become excessively charged, RAICHU plants its tail in the ground and discharges. Scorched patches of ground will be found near this MOéMON's nest.");
static const u8 sMpDexSapphire_Raichu[] = _("This MOéMON exudes a weak electrical charge from all over its body that makes it take on a slight glow in darkness. RAICHU searches for electricity by planting its tail in the ground.");
static const u8 sMpDexFireRed_Raichu[] = _("Its electric charges can reach even 100,000 volts. Careless contact can cause even an Indian elephant to faint.");
static const u8 sMpDexRuby_Sandshrew[] = _("SANDSHREW's body is configured to absorb water without waste, enabling it to survive in an arid desert. This MOéMON curls up to protect itself from its enemies.");
static const u8 sMpDexSapphire_Sandshrew[] = _("SANDSHREW has a very dry hide that is extremely tough. The MOéMON can roll into a ball that repels any attack. At night, it burrows into the desert sand to sleep.");
static const u8 sMpDexFireRed_Sandshrew[] = _("It burrows and lives underground. If threatened, it curls itself up into a ball for protection.");
static const u8 sMpDexRuby_Sandslash[] = _("SANDSLASH's body is covered by tough spikes, which are hardened sections of its hide. Once a year, the old spikes fall out, to be replaced with new spikes that grow out from beneath the old ones.");
static const u8 sMpDexSapphire_Sandslash[] = _("SANDSLASH can roll up its body as if it were a ball covered with large spikes. In battle, this MOéMON will try to make the foe flinch by jabbing it with its spines. It then leaps at the stunned foe to tear wildly with its sharp claws.");
static const u8 sMpDexFireRed_Sandslash[] = _("It is adept at attacking with the spines on its back and its sharp claws while quickly scurrying about.");
static const u8 sMpDexRuby_NidoranF[] = _("NIDORAN has barbs that secrete a powerful poison. They are thought to have developed as protection for this small-bodied MOéMON. When enraged, it releases a horrible toxin from its horn.");
static const u8 sMpDexFireRed_NidoranF[] = _("Though small, it must be treated with caution because of its powerfully toxic barbs. The female has smaller horns.");
static const u8 sMpDexRuby_Nidorina[] = _("When NIDORINA are with their friends or family, they keep their barbs tucked away to prevent hurting each other. This MOéMON appears to become nervous if separated from the others.");
static const u8 sMpDexFireRed_Nidorina[] = _("The female has a gentle temperament. It emits ultrasonic cries that have the power to befuddle foes.");
static const u8 sMpDexRuby_Nidoqueen[] = _("NIDOQUEEN's body is encased in extremely hard scales. It is adept at sending foes flying with harsh tackles. This MOéMON is at its strongest when it is defending its young.");
static const u8 sMpDexFireRed_Nidoqueen[] = _("The body is covered by stiff, needle-like scales. If it becomes excited, the needles bristle outwards.");
static const u8 sMpDexRuby_NidoranM[] = _("The male NIDORAN has developed muscles for moving its ears. Thanks to them, the ears can be freely moved in any direction. Even the slightest sound does not escape this MOéMON's notice.");
static const u8 sMpDexFireRed_NidoranM[] = _("Its large ears are flapped like wings when it is listening to distant sounds. It extends toxic barbs when angered.");
static const u8 sMpDexRuby_Nidorino[] = _("NIDORINO has a horn that is harder than a diamond. If it senses a hostile presence, all the barbs on its back bristle up at once, and it challenges the foe with all its might.");
static const u8 sMpDexFireRed_Nidorino[] = _("It is easily angered. By swinging its well-developed horn wildly, it can even punch through diamond.");
static const u8 sMpDexRuby_Nidoking[] = _("NIDOKING's thick tail packs enormously destructive power. With one swing, it can topple a metal transmission tower. Once this MOéMON goes on a rampage, there is no stopping it.");
static const u8 sMpDexFireRed_Nidoking[] = _("It is recognized by its rock-hard hide and its extended horn. Be careful with the horn as it contains venom.");
static const u8 sMpDexRuby_Clefairy[] = _("On every night of a full moon, groups of this MOéMON come out to play. When dawn arrives, the tired CLEFAIRY return to their quiet mountain retreats and go to sleep nestled up against each other.");
static const u8 sMpDexFireRed_Clefairy[] = _("Its adorable appearance makes it popular as a pet. However, it is rare and difficult to find.");
static const u8 sMpDexRuby_Clefable[] = _("CLEFABLE moves by skipping lightly as if it were flying using its wings. Its bouncy step lets it even walk on water. It is known to take strolls on lakes on quiet, moonlit nights.");
static const u8 sMpDexFireRed_Clefable[] = _("It has an acute sense of hearing. It can easily hear a pin being dropped nearly 1,100 yards away.");
static const u8 sMpDexRuby_Vulpix[] = _("At the time of its birth, VULPIX has one white tail. The tail separates into six if this MOéMON receives plenty of love from its TRAINER. The six tails become magnificently curled.");
static const u8 sMpDexSapphire_Vulpix[] = _("Inside VULPIX's body burns a flame that never goes out. During the daytime, when the temperatures rise, this MOéMON releases flames from its mouth to prevent its body from growing too hot.");
static const u8 sMpDexFireRed_Vulpix[] = _("While young, it has six gorgeous tails. When it grows, several new tails are sprouted.");
static const u8 sMpDexRuby_Ninetales[] = _("NINETALES casts a sinister light from its bright red eyes to gain total control over its foe's mind. This MOéMON is said to live for a thousand years.");
static const u8 sMpDexSapphire_Ninetales[] = _("Legend has it that NINETALES came into being when nine wizards possessing sacred powers merged into one. This MOéMON is highly intelligent - it can understand human speech.");
static const u8 sMpDexFireRed_Ninetales[] = _("It has nine long tails and fur that gleams gold. It is said to live for 1,000 years.");
static const u8 sMpDexRuby_Jigglypuff[] = _("JIGGLYPUFF's vocal chords can freely adjust the wavelength of its voice. This MOéMON uses this ability to sing at precisely the right wavelength to make its foes most drowsy.");
static const u8 sMpDexSapphire_Jigglypuff[] = _("When this MOéMON sings, it never pauses to breathe. If it is in a battle against an opponent that does not easily fall asleep, JIGGLYPUFF cannot breathe, endangering its life.");
static const u8 sMpDexFireRed_Jigglypuff[] = _("It captivates foes with its huge, round eyes, then lulls them to sleep by singing a soothing melody.");
static const u8 sMpDexRuby_Wigglytuff[] = _("WIGGLYTUFF has large, saucerlike eyes. The surfaces of its eyes are always covered with a thin layer of tears. If any dust gets in this MOéMON's eyes, it is quickly washed away.");
static const u8 sMpDexSapphire_Wigglytuff[] = _("WIGGLYTUFF's body is very flexible. By inhaling deeply, this MOéMON can inflate itself seemingly without end. Once inflated, WIGGLYTUFF bounces along lightly like a balloon.");
static const u8 sMpDexFireRed_Wigglytuff[] = _("Its fur is extremely fine, dense, and supple. The exquisitely pleasant fur conveys an image of luxury.");
static const u8 sMpDexRuby_Zubat[] = _("ZUBAT remains quietly unmoving in a dark spot during the bright daylight hours. It does so because prolonged exposure to the sun causes its body to become slightly burned.");
static const u8 sMpDexSapphire_Zubat[] = _("ZUBAT avoids sunlight because exposure causes it to become unhealthy. During the daytime, it stays in caves or under the eaves of old houses, sleeping while hanging upside down.");
static const u8 sMpDexFireRed_Zubat[] = _("It has no eyes. Instead, it relies on its ultrasonic cries for echo location to flit about in darkness.");
static const u8 sMpDexRuby_Golbat[] = _("GOLBAT loves to drink the blood of living things. It is particularly active in the pitch black of night. This MOéMON flits around in the night skies, seeking fresh blood.");
static const u8 sMpDexSapphire_Golbat[] = _("GOLBAT bites down on prey with its four fangs and drinks the victim's blood. It becomes active on inky dark moonless nights, flying around to attack people and MOéMON.");
static const u8 sMpDexFireRed_Golbat[] = _("It clamps down on its prey with needle-sharp fangs and drains over 10 ounces of blood in one gulp.");
static const u8 sMpDexRuby_Oddish[] = _("During the daytime, ODDISH buries itself in soil to absorb nutrients from the ground using its entire body. The more fertile the soil, the glossier its leaves become.");
static const u8 sMpDexSapphire_Oddish[] = _("ODDISH searches for fertile, nutrient-rich soil, then plants itself. During the daytime, while it is planted, this MOéMON's feet are thought to change shape and become similar to the roots of trees.");
static const u8 sMpDexFireRed_Oddish[] = _("Its scientific name is “Oddium Wanderus.” At night, it is said to walk nearly 1,000 feet on its two roots.");
static const u8 sMpDexRuby_Gloom[] = _("GLOOM releases a foul fragrance from the pistil of its flower. When faced with danger, the stench worsens. If this MOéMON is feeling calm and secure, it does not release its usual stinky aroma.");
static const u8 sMpDexSapphire_Gloom[] = _("From its mouth GLOOM drips honey that smells absolutely horrible. Apparently, it loves the horrid stench. It sniffs the noxious fumes and then drools even more of its honey.");
static const u8 sMpDexFireRed_Gloom[] = _("Its pistils exude an incredibly foul odor. The horrid stench can cause fainting at a distance of 1.25 miles.");
static const u8 sMpDexRuby_Vileplume[] = _("VILEPLUME's toxic pollen triggers atrocious allergy attacks. That's why it is advisable never to approach any attractive flowers in a jungle, however pretty they may be.");
static const u8 sMpDexSapphire_Vileplume[] = _("VILEPLUME has the world's largest petals. They are used to attract prey that are then doused with toxic spores. Once the prey are immobilized, this MOéMON catches and devours them.");
static const u8 sMpDexFireRed_Vileplume[] = _("Its petals are the largest in the world. It fiendishly scatters allergy-causing pollen from its petals.");
static const u8 sMpDexRuby_Paras[] = _("PARAS has parasitic mushrooms growing on its back called tochukaso. They grow large by drawing nutrients from the BUG MOéMON host. They are highly valued as a medicine for extending life.");
static const u8 sMpDexSapphire_Paras[] = _("PARAS has parasitic mushrooms growing on its back called tochukaso. They grow large by drawing nutrients from this BUG/GRASS MOéMON host. They are highly valued as a medicine for extending life.");
static const u8 sMpDexFireRed_Paras[] = _("Growing out of the bug's back are mushrooms called tochukaso. The mushrooms grow with the bug host.");
static const u8 sMpDexRuby_Parasect[] = _("PARASECT is known to infest large trees en masse and drain nutrients from the lower trunk and roots. When an infested tree dies, they move onto another tree all at once.");
static const u8 sMpDexFireRed_Parasect[] = _("It scatters toxic spores from the mushroom cap. In China, the spores are used as herbal medicine.");
static const u8 sMpDexRuby_Venonat[] = _("VENONAT is said to have evolved with a coat of thin, stiff hair that covers its entire body for protection. It possesses large eyes that never fail to spot even miniscule prey.");
static const u8 sMpDexFireRed_Venonat[] = _("Its eyes act as radar, enabling it to be active in darkness. The eyes can also shoot powerful beams.");
static const u8 sMpDexRuby_Venomoth[] = _("VENOMOTH is nocturnal - it is a MOéMON that only becomes active at night. Its favorite prey are small insects that gather around streetlights, attracted by the light in the darkness.");
static const u8 sMpDexFireRed_Venomoth[] = _("The wings are covered with dustlike scales. Every time it flaps its wings, it looses highly toxic dust.");
static const u8 sMpDexRuby_Diglett[] = _("DIGLETT are raised in most farms. The reason is simple - wherever this MOéMON burrows, the soil is left perfectly tilled for planting crops. This soil is made ideal for growing delicious vegetables.");
static const u8 sMpDexFireRed_Diglett[] = _("It burrows through the ground at a shallow depth. It leaves raised earth in its wake, making it easy to spot.");
static const u8 sMpDexRuby_Dugtrio[] = _("DUGTRIO are actually triplets that emerged from one body. As a result, each triplet thinks exactly like the other two triplets. They work cooperatively to burrow endlessly.");
static const u8 sMpDexFireRed_Dugtrio[] = _("In battle, it digs through the ground and strikes the unsuspecting foe from an unexpected direction.");
static const u8 sMpDexRuby_Meowth[] = _("MEOWTH withdraws its sharp claws into its paws to slinkily sneak about without making any incriminating footsteps. For some reason, this MOéMON loves shiny coins that glitter with light.");
static const u8 sMpDexFireRed_Meowth[] = _("All it does is sleep during the daytime. At night, it patrols its territory with its eyes aglow.");
static const u8 sMpDexRuby_Persian[] = _("PERSIAN has six bold whiskers that give it a look of toughness. The whiskers sense air movements to determine what is in the MOéMON's surrounding vicinity. It becomes docile if grabbed by the whiskers.");
static const u8 sMpDexFireRed_Persian[] = _("Has a vicious temperament. Beware if it raises its tail straight up. It is a signal that it is about to pounce and bite.");
static const u8 sMpDexRuby_Psyduck[] = _("PSYDUCK uses a mysterious power. When it does so, this MOéMON generates brain waves that are supposedly only seen in sleepers. This discovery spurred controversy among scholars.");
static const u8 sMpDexSapphire_Psyduck[] = _("If it uses its mysterious power, PSYDUCK can't remember having done so. It apparently can't form a memory of such an event because it goes into an altered state that is much like deep sleep.");
static const u8 sMpDexFireRed_Psyduck[] = _("It is constantly wracked by a headache. When the headache turns intense, it begins using mysterious powers.");
static const u8 sMpDexRuby_Golduck[] = _("The webbed flippers on its forelegs and hind legs and the streamlined body of GOLDUCK give it frightening speed. This MOéMON is definitely much faster than even the most athletic swimmer.");
static const u8 sMpDexSapphire_Golduck[] = _("GOLDUCK is the fastest swimmer among all MOéMON. It swims effortlessly, even in a rough, stormy sea. It sometimes rescues people from wrecked ships floundering in high seas.");
static const u8 sMpDexFireRed_Golduck[] = _("The forelegs are webbed, helping to make it an adept swimmer. It can be seen swimming elegantly in lakes, etc.");
static const u8 sMpDexRuby_Mankey[] = _("When MANKEY starts shaking and its nasal breathing turns rough, it's a sure sign that it is becoming angry. However, because it goes into a towering rage almost instantly, it is impossible for anyone to flee its wrath.");
static const u8 sMpDexFireRed_Mankey[] = _("Light and agile on its feet, and ferocious in temperament. When angered, it flies into an uncontrollable frenzy.");
static const u8 sMpDexRuby_Primeape[] = _("When PRIMEAPE becomes furious, its blood circulation is boosted. In turn, its muscles are made even stronger. However, it also becomes much less intelligent at the same time.");
static const u8 sMpDexFireRed_Primeape[] = _("It is always outrageously furious. If it gives chase, it will tenaciously track the target no matter how far.");
static const u8 sMpDexRuby_Growlithe[] = _("GROWLITHE has a superb sense of smell. Once it smells anything, this MOéMON won't forget the scent, no matter what. It uses its advanced olfactory sense to determine the emotions of other living things.");
static const u8 sMpDexFireRed_Growlithe[] = _("Very friendly and faithful to people. It will try to repel enemies by barking and biting.");
static const u8 sMpDexRuby_Arcanine[] = _("ARCANINE is known for its high speed. It is said to be capable of running over 6,200 miles in a single day and night. The fire that blazes wildly within this MOéMON's body is its source of power.");
static const u8 sMpDexFireRed_Arcanine[] = _("A MOéMON that is described in Chinese legends. It is said to race at an unbelievable speed.");
static const u8 sMpDexRuby_Poliwag[] = _("POLIWAG has a very thin skin. It is possible to see the MOéMON's spiral innards right through the skin. Despite its thinness, however, the skin is also very flexible. Even sharp fangs bounce right off it.");
static const u8 sMpDexFireRed_Poliwag[] = _("Its slick black skin is thin and damp. A part of its internal organs can be seen through the skin as a spiral pattern.");
static const u8 sMpDexRuby_Poliwhirl[] = _("The surface of POLIWHIRL's body is always wet and slick with an oily fluid. Because of this greasy covering, it can easily slip and slide out of the clutches of any enemy in battle.");
static const u8 sMpDexFireRed_Poliwhirl[] = _("Its two legs are well developed. Even though it can live on the ground, it prefers living in water.");
static const u8 sMpDexRuby_Poliwrath[] = _("POLIWRATH's highly developed, brawny muscles never grow fatigued, however much it exercises. It is so tirelessly strong, this MOéMON can swim back and forth across the Pacific Ocean without effort.");
static const u8 sMpDexFireRed_Poliwrath[] = _("An adept swimmer, it knows the front crawl, butterfly, and more. It is faster than the best human swimmers.");
static const u8 sMpDexRuby_Abra[] = _("ABRA sleeps for eighteen hours a day. However, it can sense the presence of foes even while it is sleeping. In such a situation, this MOéMON immediately teleports to safety.");
static const u8 sMpDexSapphire_Abra[] = _("ABRA needs to sleep for eighteen hours a day. If it doesn't, this MOéMON loses its ability to use telekinetic powers. If it is attacked, ABRA escapes using TELEPORT while it is still sleeping.");
static const u8 sMpDexFireRed_Abra[] = _("It sleeps for 18 hours a day. It uses a variety of extrasensory powers even while asleep.");
static const u8 sMpDexRuby_Kadabra[] = _("KADABRA emits a peculiar alpha wave if it develops a headache. Only those people with a particularly strong psyche can hope to become a TRAINER of this MOéMON.");
static const u8 sMpDexSapphire_Kadabra[] = _("KADABRA holds a silver spoon in its hand. The spoon is used to amplify the alpha waves in its brain. Without the spoon, the MOéMON is said to be limited to half the usual amount of its telekinetic powers.");
static const u8 sMpDexFireRed_Kadabra[] = _("It happened one morning - a boy with extrasensory powers awoke in bed transformed into KADABRA.");
static const u8 sMpDexRuby_Alakazam[] = _("ALAKAZAM's brain continually grows, making its head far too heavy to support with its neck. This MOéMON holds its head up using its psychokinetic power instead.");
static const u8 sMpDexSapphire_Alakazam[] = _("ALAKAZAM's brain continually grows, infinitely multiplying brain cells. This amazing brain gives this MOéMON an astoundingly high IQ of 5,000. It has a thorough memory of everything that has occurred in the world.");
static const u8 sMpDexFireRed_Alakazam[] = _("It does not like physical attacks very much. Instead, it freely uses extra-sensory powers to defeat foes.");
static const u8 sMpDexRuby_Machop[] = _("MACHOP's muscles are special - they never get sore no matter how much they are used in exercise. This MOéMON has sufficient power to hurl a hundred adult humans.");
static const u8 sMpDexSapphire_Machop[] = _("MACHOP exercises by hefting around a GRAVELER as if it were a barbell. There are some MACHOP that travel the world in a quest to master all kinds of martial arts.");
static const u8 sMpDexFireRed_Machop[] = _("Its whole body is composed of muscles. Even though it's the size of a human child, it can hurl 100 grown-ups.");
static const u8 sMpDexRuby_Machoke[] = _("MACHOKE's thoroughly toned muscles possess the hardness of steel. This MOéMON has so much strength, it can easily hold aloft a sumo wrestler on just one finger.");
static const u8 sMpDexSapphire_Machoke[] = _("MACHOKE undertakes bodybuilding every day even as it helps people with tough, physically demanding labor. On its days off, this MOéMON heads to the fields and mountains to exercise and train.");
static const u8 sMpDexFireRed_Machoke[] = _("Its formidable body never gets tired. It helps people by doing work such as the moving of heavy goods.");
static const u8 sMpDexRuby_Machamp[] = _("MACHAMP has the power to hurl anything aside. However, trying to do any work requiring care and dexterity causes its arms to get tangled. This MOéMON tends to leap into action before it thinks.");
static const u8 sMpDexSapphire_Machamp[] = _("MACHAMP is known as the MOéMON that has mastered every kind of martial arts. If it grabs hold of the foe with its four arms, the battle is all but over. The hapless foe is thrown far over the horizon.");
static const u8 sMpDexFireRed_Machamp[] = _("Its four ruggedly developed arms can launch a flurry of 1,000 punches in just two seconds.");
static const u8 sMpDexRuby_Bellsprout[] = _("BELLSPROUT's thin and flexible body lets it bend and sway to avoid any attack, however strong it may be. From its mouth, this MOéMON spits a corrosive fluid that melts even iron.");
static const u8 sMpDexFireRed_Bellsprout[] = _("Its bud looks like a human face. Because of the bud, it is rumored to be a type of legendary mandrake plant.");
static const u8 sMpDexRuby_Weepinbell[] = _("WEEPINBELL has a large hook on its rear end. At night, the MOéMON hooks on to a tree branch and goes to sleep. If it moves around in its sleep, it may wake up to find itself on the ground.");
static const u8 sMpDexFireRed_Weepinbell[] = _("The leafy parts act as cutters for slashing foes. It spits a fluid that dissolves everything.");
static const u8 sMpDexRuby_Victreebel[] = _("VICTREEBEL has a long vine that extends from its head. This vine is waved and flicked about as if it were an animal to attract prey. When an unsuspecting prey draws near, this MOéMON swallows it whole.");
static const u8 sMpDexFireRed_Victreebel[] = _("Lures prey into its mouth with a honeylike aroma. The helpless prey is melted with a dissolving fluid.");
static const u8 sMpDexRuby_Tentacool[] = _("TENTACOOL's body is largely composed of water. If it is removed from the sea, it dries up like parchment. If this MOéMON happens to become dehydrated, put it back into the sea.");
static const u8 sMpDexSapphire_Tentacool[] = _("TENTACOOL absorbs sunlight and refracts it using water inside its body to convert it into beam energy. This MOéMON shoots beams from its crystal-like eyes.");
static const u8 sMpDexFireRed_Tentacool[] = _("Its eyes are as transparent as crystals. From them, it shoots mysterious beams of light.");
static const u8 sMpDexRuby_Tentacruel[] = _("TENTACRUEL has large red orbs on its head. The orbs glow before lashing the vicinity with a harsh ultrasonic blast. This MOéMON's outburst creates rough waves around it.");
static const u8 sMpDexSapphire_Tentacruel[] = _("TENTACRUEL has tentacles that can be freely elongated and shortened at will. It ensnares prey with its tentacles and weakens the prey by dosing it with a harsh toxin. It can catch up to 80 prey at the same time.");
static const u8 sMpDexFireRed_Tentacruel[] = _("It has 80 tentacles that move about freely. They can sting, causing poisoning and sharp, stabbing pain.");
static const u8 sMpDexRuby_Geodude[] = _("The longer a GEODUDE lives, the more its edges are chipped and worn away, making it more rounded in appearance. However, this MOéMON's heart will remain hard, craggy, and rough always.");
static const u8 sMpDexSapphire_Geodude[] = _("When GEODUDE sleeps deeply, it buries itself halfway into the ground. It will not awaken even if hikers step on it unwittingly. In the morning, this MOéMON rolls downhill in search of food.");
static const u8 sMpDexFireRed_Geodude[] = _("Its round form makes it easy to pick up. Some people have used them to hurl at each other in a snowball fight.");
static const u8 sMpDexRuby_Graveler[] = _("GRAVELER grows by feeding on rocks. Apparently, it prefers to eat rocks that are covered in moss. This MOéMON eats its way through a ton of rocks on a daily basis.");
static const u8 sMpDexSapphire_Graveler[] = _("Rocks are GRAVELER's favorite food. This MOéMON will climb a mountain from the base to the summit, crunchingly feasting on rocks all the while. Upon reaching the peak, it rolls back down to the bottom.");
static const u8 sMpDexFireRed_Graveler[] = _("Be careful while hiking on mountain trails. GRAVELER may come rolling down the path without slowing.");
static const u8 sMpDexRuby_Golem[] = _("GOLEM live up on mountains. If there is a large earthquake, these MOéMON will come rolling down off the mountains en masse to the foothills below.");
static const u8 sMpDexSapphire_Golem[] = _("GOLEM is known for rolling down from mountains. To prevent them from rolling into the homes of people downhill, grooves have been dug into the sides of mountains to serve as guideways for diverting this MOéMON's course.");
static const u8 sMpDexFireRed_Golem[] = _("It is enclosed in a hard shell that is as rugged as slabs of rock. It sheds skin once a year to grow larger.");
static const u8 sMpDexRuby_Ponyta[] = _("PONYTA is very weak at birth. It can barely stand up. This MOéMON becomes stronger by stumbling and falling to keep up with its parent.");
static const u8 sMpDexFireRed_Ponyta[] = _("Its body is light, and its legs are incredibly powerful. It can clear Ayers Rock in one leap.");
static const u8 sMpDexRuby_Rapidash[] = _("RAPIDASH usually can be seen casually cantering in the fields and plains. However, when this MOéMON turns serious, its fiery manes flare and blaze as it gallops its way up to 150 mph.");
static const u8 sMpDexFireRed_Rapidash[] = _("It can gallop at a top speed of 150 miles per hour. It can race as fast as a bullet train while ablaze.");
static const u8 sMpDexRuby_Slowpoke[] = _("SLOWPOKE uses its tail to catch prey by dipping it in water at the side of a river. However, this MOéMON often forgets what it's doing and often spends entire days just loafing at water's edge.");
static const u8 sMpDexFireRed_Slowpoke[] = _("It is always vacantly lost in thought, but no one knows what it is thinking about. It is good at fishing with its tail.");
static const u8 sMpDexRuby_Slowbro[] = _("SLOWBRO's tail has a SHELLDER firmly attached with a bite. As a result, the tail can't be used for fishing anymore. This causes SLOWBRO to grudgingly swim and catch prey instead.");
static const u8 sMpDexFireRed_Slowbro[] = _("When a SLOWPOKE went hunting in the sea, its tail was bitten by a SHELLDER. That made it evolve into SLOWBRO.");
static const u8 sMpDexRuby_Magnemite[] = _("MAGNEMITE attaches itself to power lines to feed on electricity. If your house has a power outage, check your circuit breakers. You may find a large number of this MOéMON clinging to the breaker box.");
static const u8 sMpDexSapphire_Magnemite[] = _("MAGNEMITE floats in the air by emitting electromagnetic waves from the units at its sides. These waves block gravity. This MOéMON becomes incapable of flight if its internal electrical supply is depleted.");
static const u8 sMpDexFireRed_Magnemite[] = _("It moves while constantly hovering. It discharges THUNDER WAVE and so on from the units at its sides.");
static const u8 sMpDexRuby_Magneton[] = _("MAGNETON emits a powerful magnetic force that is fatal to mechanical devices. As a result, large cities sound sirens to warn citizens of large-scale outbreaks of this MOéMON.");
static const u8 sMpDexSapphire_Magneton[] = _("MAGNETON emits a powerful magnetic force that is fatal to electronics and precision instruments. Because of this, it is said that some towns warn people to keep this MOéMON inside a POKé BALL.");
static const u8 sMpDexFireRed_Magneton[] = _("A linked cluster formed of several MAGNEMITE. It discharges powerful magnetic waves at high voltage.");
static const u8 sMpDexRuby_Farfetchd[] = _("FARFETCH'D is always seen with a stick from a plant of some sort. Apparently, there are good sticks and bad sticks. This MOéMON has been known to fight with others over sticks.");
static const u8 sMpDexFireRed_Farfetchd[] = _("It always walks about with a plant stalk clamped in its beak. The stalk is used for building its nest.");
static const u8 sMpDexRuby_Doduo[] = _("DODUO's two heads never sleep at the same time. Its two heads take turns sleeping, so one head can always keep watch for enemies while the other one sleeps.");
static const u8 sMpDexSapphire_Doduo[] = _("DODUO's two heads contain completely identical brains. A scientific study reported that on rare occasions, there will be examples of this MOéMON possessing different sets of brains.");
static const u8 sMpDexFireRed_Doduo[] = _("A two-headed MOéMON that was discovered as a sudden mutation. It runs at a pace of over 60 miles per hour.");
static const u8 sMpDexRuby_Dodrio[] = _("Watch out if DODRIO's three heads are looking in three separate directions. It's a sure sign that it is on its guard. Don't go near this MOéMON if it's being wary - it may decide to peck you.");
static const u8 sMpDexSapphire_Dodrio[] = _("Apparently, the heads aren't the only parts of the body that DODRIO has three of. It has three sets of hearts and lungs as well, so it is capable of running long distances without rest.");
static const u8 sMpDexFireRed_Dodrio[] = _("An odd species that is rarely found. The three heads respectively represent joy, sadness, and anger.");
static const u8 sMpDexRuby_Seel[] = _("SEEL hunts for prey in the frigid sea underneath sheets of ice. When it needs to breathe, it punches a hole through the ice with the sharply protruding section of its head.");
static const u8 sMpDexFireRed_Seel[] = _("Covered with light blue fur, its hide is thick and tough. It is active in bitter cold of minus 40 degrees Fahrenheit.");
static const u8 sMpDexRuby_Dewgong[] = _("DEWGONG loves to snooze on bitterly cold ice. The sight of this MOéMON sleeping on a glacier was mistakenly thought to be a mermaid by a mariner long ago.");
static const u8 sMpDexFireRed_Dewgong[] = _("Its body is covered with a pure white fur. The colder the weather, the more active it becomes.");
static const u8 sMpDexRuby_Grimer[] = _("GRIMER's sludgy and rubbery body can be forced through any opening, however small it may be. This MOéMON enters sewer pipes to drink filthy wastewater.");
static const u8 sMpDexSapphire_Grimer[] = _("GRIMER emerged from the sludge that settled on a polluted seabed. This MOéMON loves anything filthy. It constantly leaks a horribly germ-infested fluid from all over its body.");
static const u8 sMpDexFireRed_Grimer[] = _("Sludge exposed to X rays from the moon transformed into GRIMER. It loves feeding on filthy things.");
static const u8 sMpDexRuby_Muk[] = _("From MUK's body seeps a foul fluid that gives off a nose-bendingly horrible stench. Just one drop of this MOéMON's body fluid can turn a pool stagnant and rancid.");
static const u8 sMpDexSapphire_Muk[] = _("This MOéMON's favorite food is anything that is repugnantly filthy. In dirty towns where people think nothing of throwing away litter on the streets, MUK are certain to gather.");
static const u8 sMpDexFireRed_Muk[] = _("It is usually undetectable because it blends in with the ground. Touching it can cause terrible poisoning.");
static const u8 sMpDexRuby_Shellder[] = _("At night, this MOéMON uses its broad tongue to burrow a hole in the seafloor sand and then sleep in it. While it is sleeping, SHELLDER closes its shell, but leaves its tongue hanging out.");
static const u8 sMpDexFireRed_Shellder[] = _("It is encased in a shell that is harder than diamond. Inside, however, it is surprisingly tender.");
static const u8 sMpDexRuby_Cloyster[] = _("CLOYSTER is capable of swimming in the sea. It does so by swallowing water, then jetting it out toward the rear. This MOéMON shoots spikes from its shell using the same system.");
static const u8 sMpDexFireRed_Cloyster[] = _("Its shell is extremely hard. It cannot be shattered, even with a bomb. The shell opens only when it is attacking.");
static const u8 sMpDexRuby_Gastly[] = _("GASTLY is largely composed of gaseous matter. When exposed to a strong wind, the gaseous body quickly dwindles away. Groups of this MOéMON cluster under the eaves of houses to escape the ravages of wind.");
static const u8 sMpDexFireRed_Gastly[] = _("A being that exists as a thin gas. It can topple an Indian elephant by enveloping the prey in two seconds.");
static const u8 sMpDexRuby_Haunter[] = _("HAUNTER is a dangerous MOéMON. If one beckons you while floating in darkness, you must never approach it. This MOéMON will try to lick you with its tongue and steal your life away.");
static const u8 sMpDexFireRed_Haunter[] = _("If you get the feeling of being watched in darkness when nobody is around, HAUNTER is there.");
static const u8 sMpDexRuby_Gengar[] = _("Sometimes, on a dark night, your shadow thrown by a streetlight will suddenly and startlingly overtake you. It is actually a GENGAR running past you, pretending to be your shadow.");
static const u8 sMpDexFireRed_Gengar[] = _("It is said to emerge from darkness to steal the lives of those who become lost in mountains.");
static const u8 sMpDexRuby_Onix[] = _("ONIX has a magnet in its brain. It acts as a compass so that this MOéMON does not lose direction while it is tunneling. As it grows older, its body becomes increasingly rounder and smoother.");
static const u8 sMpDexFireRed_Onix[] = _("It usually lives underground. It searches for food while boring its way through the ground at 50 miles per hour.");
static const u8 sMpDexRuby_Drowzee[] = _("If your nose becomes itchy while you are sleeping, it's a sure sign that one of these MOéMON is standing above your pillow and trying to eat your dream through your nostrils.");
static const u8 sMpDexFireRed_Drowzee[] = _("A descendent of the legendary animal baku, which is said to eat dreams. It is skilled at hypnotism.");
static const u8 sMpDexRuby_Hypno[] = _("HYPNO holds a pendulum in its hand. The arcing movement and glitter of the pendulum lull the foe into a deep state of hypnosis. While this MOéMON searches for prey, it polishes the pendulum.");
static const u8 sMpDexFireRed_Hypno[] = _("It carries a pendulum-like device. There once was an incident in which it took away a child it hypnotized.");
static const u8 sMpDexRuby_Krabby[] = _("KRABBY live on beaches, burrowed inside holes dug into the sand. On sandy beaches with little in the way of food, these MOéMON can be seen squabbling with each other over territory.");
static const u8 sMpDexFireRed_Krabby[] = _("It can be found near the sea. The large pincers grow back if they are torn out of their sockets.");
static const u8 sMpDexRuby_Kingler[] = _("KINGLER has an enormous, oversized claw. It waves this huge claw in the air to communicate with others. However, because the claw is so heavy, the MOéMON quickly tires.");
static const u8 sMpDexFireRed_Kingler[] = _("Its large and hard pincer has 10,000-horsepower strength. However, being so big, it is unwieldy to move.");
static const u8 sMpDexRuby_Voltorb[] = _("VOLTORB was first sighted at a company that manufactures POKé BALLS. The link between that sighting and the fact that this MOéMON looks very similar to a POKé BALL remains a mystery.");
static const u8 sMpDexSapphire_Voltorb[] = _("VOLTORB is extremely sensitive - it explodes at the slightest of shocks. It is rumored that it was first created when a POKé BALL was exposed to a powerful pulse of energy.");
static const u8 sMpDexFireRed_Voltorb[] = _("A life-form whose identity is unknown. It is said to SCREECH or suddenly SELFDESTRUCT.");
static const u8 sMpDexRuby_Electrode[] = _("ELECTRODE eats electricity in the atmosphere. On days when lightning strikes, you can see this MOéMON exploding all over the place from eating too much electricity.");
static const u8 sMpDexSapphire_Electrode[] = _("One of ELECTRODE's characteristics is its attraction to electricity. It is a problematical MOéMON that congregates mostly at electrical power plants to feed on electricity that has just been generated.");
static const u8 sMpDexFireRed_Electrode[] = _("It explodes in response to even minor stimuli. It is feared, with the nickname of “The Bomb Ball.”");
static const u8 sMpDexRuby_Exeggcute[] = _("This MOéMON consists of six eggs that form a closely knit cluster. The six eggs attract each other and spin around. When cracks increasingly appear on the eggs, EXEGGCUTE is close to evolution.");
static const u8 sMpDexFireRed_Exeggcute[] = _("Even though it appears to be eggs of some sort, it was discovered to be a life-form more like plant seeds.");
static const u8 sMpDexRuby_Exeggutor[] = _("EXEGGUTOR originally came from the tropics. Its heads steadily grow larger from exposure to strong sunlight. It is said that when the heads fall off, they group together to form EXEGGCUTE.");
static const u8 sMpDexFireRed_Exeggutor[] = _("It is called “The Walking Tropical Rainforest.” Each of the nuts has a face and a will of its own.");
static const u8 sMpDexRuby_Cubone[] = _("CUBONE pines for the mother it will never see again. Seeing a likeness of its mother in the full moon, it cries. The stains on the skull the MOéMON wears are made by the tears it sheds.");
static const u8 sMpDexFireRed_Cubone[] = _("It wears the skull of its dead mother on its head. When it becomes lonesome, it is said to cry loudly.");
static const u8 sMpDexRuby_Marowak[] = _("MAROWAK is the evolved form of a CUBONE that has overcome its sadness at the loss of its mother and grown tough. This MOéMON's tempered and hardened spirit is not easily broken.");
static const u8 sMpDexFireRed_Marowak[] = _("It is small and was originally very weak. Its temperament turned ferocious when it began using bones.");
static const u8 sMpDexRuby_Hitmonlee[] = _("HITMONLEE's legs freely contract and stretch. Using these springlike legs, it bowls over foes with devastating kicks. After battle, it rubs down its legs and loosens the muscles to overcome fatigue.");
static const u8 sMpDexFireRed_Hitmonlee[] = _("The legs freely contract and stretch. The stretchy legs allow it to hit a distant foe with a rising kick.");
static const u8 sMpDexRuby_Hitmonchan[] = _("HITMONCHAN is said to possess the spirit of a boxer who had been working towards a world championship. This MOéMON has an indomitable spirit and will never give up in the face of adversity.");
static const u8 sMpDexFireRed_Hitmonchan[] = _("The spirit of a pro boxer has infused this MOéMON. It throws punches that are faster than a bullet train.");
static const u8 sMpDexRuby_Lickitung[] = _("Whenever LICKITUNG comes across something new, it will unfailingly give it a lick. It does so because it memorizes things by texture and by taste. It is somewhat put off by sour things.");
static const u8 sMpDexFireRed_Lickitung[] = _("Its tongue is twice the length of its body. It can be moved like an arm for grabbing food and attacking.");
static const u8 sMpDexRuby_Koffing[] = _("If KOFFING becomes agitated, it raises the toxicity of its internal gases and jets them out from all over its body. This MOéMON may also overinflate its round body, then explode.");
static const u8 sMpDexSapphire_Koffing[] = _("KOFFING embodies toxic substances. It mixes the toxins with raw garbage to set off a chemical reaction that results in a terribly powerful poison gas. The higher the temperature, the more gas is concocted by this MOéMON.");
static const u8 sMpDexFireRed_Koffing[] = _("Its thin, balloon-like body is inflated by horribly toxic gases. It reeks when it is nearby.");
static const u8 sMpDexRuby_Weezing[] = _("WEEZING loves the gases given off by rotted kitchen garbage. This MOéMON will find a dirty, unkempt house and make it its home. At night, when the people in the house are asleep, it will go through the trash.");
static const u8 sMpDexSapphire_Weezing[] = _("WEEZING alternately shrinks and inflates its twin bodies to mix together toxic gases inside. The more the gases are mixed, the more powerful the toxins become. The MOéMON also becomes more putrid.");
static const u8 sMpDexFireRed_Weezing[] = _("Very rarely, a sudden mutation can result in two small KOFFING twins becoming conjoined as a WEEZING.");
static const u8 sMpDexRuby_Rhyhorn[] = _("RHYHORN runs in a straight line, smashing everything in its path. It is not bothered even if it rushes headlong into a block of steel. This MOéMON may feel some pain from the collision the next day, however.");
static const u8 sMpDexSapphire_Rhyhorn[] = _("RHYHORN's brain is very small. It is so dense, while on a run it forgets why it started running in the first place. It apparently remembers sometimes if it demolishes something.");
static const u8 sMpDexFireRed_Rhyhorn[] = _("Strong, but not too bright, this MOéMON can shatter even a skyscraper with its charging TACKLES.");
static const u8 sMpDexRuby_Rhydon[] = _("RHYDON's horn can crush even uncut diamonds. One sweeping blow of its tail can topple a building. This MOéMON's hide is extremely tough. Even direct cannon hits don't leave a scratch.");
static const u8 sMpDexSapphire_Rhydon[] = _("RHYDON has a horn that serves as a drill. It is used for destroying rocks and boulders. This MOéMON occasionally rams into streams of magma, but the armor-like hide prevents it from feeling the heat.");
static const u8 sMpDexFireRed_Rhydon[] = _("It begins walking on its hind legs after evolution. It can punch holes through boulders with its horn.");
static const u8 sMpDexRuby_Chansey[] = _("CHANSEY lays nutritionally excellent eggs on an everyday basis. The eggs are so delicious, they are easily and eagerly devoured by even those people who have lost their appetite.");
static const u8 sMpDexFireRed_Chansey[] = _("It lays several eggs a day. The eggs are apparently rich in nutrients and extremely delicious.");
static const u8 sMpDexRuby_Tangela[] = _("TANGELA's vines snap off easily if they are grabbed. This happens without pain, allowing it to make a quick getaway. The lost vines are replaced by newly grown vines the very next day.");
static const u8 sMpDexFireRed_Tangela[] = _("Blue plant vines cloak the MOéMON's identity in a tangled mass. It entangles anything that gets close.");
static const u8 sMpDexRuby_Kangaskhan[] = _("If you come across a young KANGASKHAN playing by itself, you must never disturb it or attempt to catch it. The baby MOéMON's parent is sure to be in the area, and it will become violently enraged at you.");
static const u8 sMpDexFireRed_Kangaskhan[] = _("The female raises its offspring in a pouch on its belly. It is skilled at attacking using COMET PUNCH.");
static const u8 sMpDexRuby_Horsea[] = _("HORSEA eats small insects and moss off of rocks. If the ocean current turns fast, this MOéMON anchors itself by wrapping its tail around rocks or coral to prevent being washed away.");
static const u8 sMpDexSapphire_Horsea[] = _("If HORSEA senses danger, it will reflexively spray a dense black ink from its mouth and try to escape. This MOéMON swims by cleverly flapping the fins on its back.");
static const u8 sMpDexFireRed_Horsea[] = _("It maintains balance using its tail, which is wound up like a coil. It may spray ink from its mouth.");
static const u8 sMpDexRuby_Seadra[] = _("SEADRA sleeps after wriggling itself between the branches of coral. Those trying to harvest coral are occasionally stung by this MOéMON's poison barbs if they fail to notice it.");
static const u8 sMpDexSapphire_Seadra[] = _("SEADRA generates whirlpools by spinning its body. The whirlpools are strong enough to swallow even fishing boats. This MOéMON weakens prey with these currents, then swallows it whole.");
static const u8 sMpDexFireRed_Seadra[] = _("Its body bristles with sharp spikes. Carelessly trying to touch it could cause fainting from the spikes.");
static const u8 sMpDexRuby_Goldeen[] = _("GOLDEEN is a very beautiful MOéMON with fins that billow elegantly in water. However, don't let your guard down around this MOéMON - it could ram you powerfully with its horn.");
static const u8 sMpDexSapphire_Goldeen[] = _("GOLDEEN loves swimming wild and free in rivers and ponds. If one of these MOéMON is placed in an aquarium, it will shatter even the thickest glass with one ram of its horn and make its escape.");
static const u8 sMpDexFireRed_Goldeen[] = _("Its dorsal and pectoral fins are strongly developed like muscles. It can swim at a speed of five knots.");
static const u8 sMpDexRuby_Seaking[] = _("In the autumn, SEAKING males can be seen performing courtship dances in riverbeds to woo females. During this season, this MOéMON's body coloration is at its most beautiful.");
static const u8 sMpDexSapphire_Seaking[] = _("SEAKING is very protective of its eggs. The male and female will take turns patrolling around their nest and eggs. The guarding of eggs by these MOéMON goes on for over a month.");
static const u8 sMpDexFireRed_Seaking[] = _("The horn on its head is sharp like a drill. It bores a hole in a boulder to make its nest.");
static const u8 sMpDexRuby_Staryu[] = _("STARYU's center section has an organ called the core that shines bright red. If you go to a beach toward the end of summer, the glowing cores of these MOéMON look like the stars in the sky.");
static const u8 sMpDexSapphire_Staryu[] = _("STARYU apparently communicates with the stars in the night sky by flashing the red core at the center of its body. If parts of its body are torn, this MOéMON simply regenerates the missing pieces and limbs.");
static const u8 sMpDexFireRed_Staryu[] = _("It appears in large numbers by seashores. At night, its central core flashes with a red light.");
static const u8 sMpDexRuby_Starmie[] = _("STARMIE's center section - the core - glows brightly in seven colors. Because of its luminous nature, this MOéMON has been given the nickname “the gem of the sea.”");
static const u8 sMpDexSapphire_Starmie[] = _("STARMIE swims through water by spinning its star-shaped body as if it were a propeller on a ship. The core at the center of this MOéMON's body glows in seven colors.");
static const u8 sMpDexFireRed_Starmie[] = _("This MOéMON has a geometric body. Because of its body, the locals suspect that it is an alien creature.");
static const u8 sMpDexRuby_MrMime[] = _("MR. MIME is a master of pantomime. Its gestures and motions convince watchers that something unseeable actually exists. Once it is believed, it will exist as if it were a real thing.");
static const u8 sMpDexFireRed_MrMime[] = _("It is adept at conning people. It is said to be able to create walls out of thin air by miming.");
static const u8 sMpDexRuby_Scyther[] = _("SCYTHER is blindingly fast. Its blazing speed enhances the effectiveness of the twin scythes on its forearms. This MOéMON's scythes are so effective, they can slice through thick logs in one wicked stroke.");
static const u8 sMpDexFireRed_Scyther[] = _("It tears and shreds prey with its wickedly sharp scythes. It very rarely spreads its wings to fly.");
static const u8 sMpDexRuby_Jynx[] = _("JYNX walks rhythmically, swaying and shaking its hips as if it were dancing. Its motions are so bouncingly alluring, people seeing it are compelled to shake their hips without giving any thought to what they are doing.");
static const u8 sMpDexFireRed_Jynx[] = _("It speaks using a language that sounds human. Research is under way to determine what is being said.");
static const u8 sMpDexRuby_Electabuzz[] = _("When a storm arrives, gangs of this MOéMON compete with each other to scale heights that are likely to be stricken by lightning bolts. Some towns use ELECTABUZZ in place of lightning rods.");
static const u8 sMpDexFireRed_Electabuzz[] = _("It loves to feed on strong electricity. It occasionally appears around large power plants and so on.");
static const u8 sMpDexRuby_Magmar[] = _("In battle, MAGMAR blows out intensely hot flames from all over its body to intimidate its opponent. This MOéMON's fiery bursts create heat waves that ignite grass and trees in its surroundings.");
static const u8 sMpDexFireRed_Magmar[] = _("Found near the mouth of a volcano. This fire-breather's body temperature is nearly 2,200 degrees Fahrenheit.");
static const u8 sMpDexRuby_Pinsir[] = _("PINSIR is astoundingly strong. It can grip a foe weighing twice its weight in its horns and easily lift it. This MOéMON's movements turn sluggish in cold places.");
static const u8 sMpDexSapphire_Pinsir[] = _("PINSIR has a pair of massive horns Protruding from the surface of these horns are thorns. These thorns are driven deeply into the foe's body when the pincer closes, making it tough for the foe to escape.");
static const u8 sMpDexFireRed_Pinsir[] = _("Its two long pincer horns are powerful. Once they grip an enemy, they won't release until the foe is torn.");
static const u8 sMpDexRuby_Tauros[] = _("This MOéMON is not satisfied unless it is rampaging at all times. If there is no opponent for TAUROS to battle, it will charge at thick trees and knock them down to calm itself.");
static const u8 sMpDexFireRed_Tauros[] = _("When it is about to TACKLE, it whips its body repeatedly with its three long tails.");
static const u8 sMpDexRuby_Magikarp[] = _("MAGIKARP is a pathetic excuse for a MOéMON that is only capable of flopping and splashing. This behavior prompted scientists to undertake research into it.");
static const u8 sMpDexSapphire_Magikarp[] = _("MAGIKARP is virtually useless in battle as it can only splash around. As a result, it is considered to be weak. However, it is actually a very hardy MOéMON that can survive in any body of water no matter how polluted it is.");
static const u8 sMpDexFireRed_Magikarp[] = _("It is virtually worthless in terms of both power and speed. It is the most weak and pathetic MOéMON in the world.");
static const u8 sMpDexRuby_Gyarados[] = _("When MAGIKARP evolves into GYARADOS, its brain cells undergo a structural transformation. It is said that this transformation is to blame for this MOéMON's wildly violent nature.");
static const u8 sMpDexSapphire_Gyarados[] = _("Once GYARADOS goes on a rampage, its ferociously violent blood doesn't calm until it has burned everything down. There are records of this MOéMON's rampages lasting a whole month.");
static const u8 sMpDexFireRed_Gyarados[] = _("It has an extremely aggressive nature. The HYPER BEAM it shoots from its mouth totally incinerates all targets.");
static const u8 sMpDexRuby_Lapras[] = _("People have driven LAPRAS almost to the point of extinction. In the evenings, this MOéMON is said to sing plaintively as it seeks what few others of its kind still remain.");
static const u8 sMpDexFireRed_Lapras[] = _("Its high intelligence enables it to understand human speech. It likes to ferry people on its back.");
static const u8 sMpDexRuby_Ditto[] = _("DITTO rearranges its cell structure to transform itself into other shapes. However, if it tries to transform itself into something by relying on its memory, this MOéMON manages to get details wrong.");
static const u8 sMpDexFireRed_Ditto[] = _("It can freely recombine its own cellular structure to transform into other life-forms.");
static const u8 sMpDexRuby_Eevee[] = _("EEVEE has an unstable genetic makeup that suddenly mutates due to the environment in which it lives. Radiation from various STONES causes this MOéMON to evolve.");
static const u8 sMpDexFireRed_Eevee[] = _("An extremely rare MOéMON that may evolve in a number of different ways depending on stimuli.");
static const u8 sMpDexRuby_Vaporeon[] = _("VAPOREON underwent a spontaneous mutation and grew fins and gills that allow it to live underwater. This MOéMON has the ability to freely control water.");
static const u8 sMpDexFireRed_Vaporeon[] = _("Its body's cellular structure is similar to the molecular composition of water. It can melt invisibly in water.");
static const u8 sMpDexRuby_Jolteon[] = _("JOLTEON's cells generate a low level of electricity. This power is amplified by the static electricity of its fur, enabling the MOéMON to drop thunderbolts. The bristling fur is made of electrically charged needles.");
static const u8 sMpDexFireRed_Jolteon[] = _("If it is angered or startled, the fur all over its body bristles like sharp needles that pierce foes.");
static const u8 sMpDexRuby_Flareon[] = _("FLAREON's fluffy fur has a functional purpose - it releases heat into the air so that its body does not get excessively hot. This MOéMON's body temperature can rise to a maximum of 1,650 degrees F.");
static const u8 sMpDexFireRed_Flareon[] = _("It has a flame bag inside its body. After inhaling deeply, it blows out flames of nearly 3,100 degrees Fahrenheit.");
static const u8 sMpDexRuby_Porygon[] = _("PORYGON is capable of reverting itself entirely back to program data and entering cyberspace. This MOéMON is copy-protected so it cannot be duplicated by copying.");
static const u8 sMpDexFireRed_Porygon[] = _("Using the most advanced technologies, scientists finally succeeded in making the first artificial MOéMON.");
static const u8 sMpDexRuby_Omanyte[] = _("OMANYTE is one of the ancient and long-since-extinct MOéMON that have been regenerated from fossils by people. If attacked by an enemy, it withdraws itself inside its hard shell.");
static const u8 sMpDexFireRed_Omanyte[] = _("A prehistoric MOéMON that lived in the primordial sea, it swims by twisting its 10 tentacles about.");
static const u8 sMpDexRuby_Omastar[] = _("OMASTAR uses its tentacles to capture its prey. It is believed to have become extinct because its shell grew too large and heavy, causing its movements to become too slow and ponderous.");
static const u8 sMpDexFireRed_Omastar[] = _("Its tentacles are highly developed as if they are hands and feet. As soon as it ensnares prey, it bites.");
static const u8 sMpDexRuby_Kabuto[] = _("KABUTO is a MOéMON that has been regenerated from a fossil. However, in extremely rare cases, living examples have been discovered. The MOéMON has not changed at all for 300 million years.");
static const u8 sMpDexFireRed_Kabuto[] = _("This MOéMON was regenerated from the fossil of an ancient creature. It protects itself with a hard shell.");
static const u8 sMpDexRuby_Kabutops[] = _("KABUTOPS swam underwater to hunt for its prey in ancient times. The MOéMON was apparently evolving from being a water-dweller to living on land as evident from the beginnings of change in its gills and legs.");
static const u8 sMpDexFireRed_Kabutops[] = _("It swims freely through water. It catches prey with its scythe-like arms and drains the victim's fluids.");
static const u8 sMpDexRuby_Aerodactyl[] = _("AERODACTYL is a MOéMON from the age of dinosaurs. It was regenerated from genetic material extracted from amber. It is imagined to have been the king of the skies in ancient times.");
static const u8 sMpDexFireRed_Aerodactyl[] = _("It was regenerated from a dinosaur's genetic matter that was found in amber. It flies with high-pitched cries.");
static const u8 sMpDexRuby_Snorlax[] = _("SNORLAX's typical day consists of nothing more than eating and sleeping. It is such a docile MOéMON that there are children who use its expansive belly as a place to play.");
static const u8 sMpDexFireRed_Snorlax[] = _("It is not satisfied unless it eats over 880 pounds of food every day. When it is done eating, it goes promptly to sleep.");
static const u8 sMpDexRuby_Articuno[] = _("ARTICUNO is a legendary bird MOéMON that can control ice. The flapping of its wings chills the air. As a result, it is said that when this MOéMON flies, snow will fall.");
static const u8 sMpDexFireRed_Articuno[] = _("One of the legendary bird MOéMON. With its long tail trailing behind, its flying form is magnificent.");
static const u8 sMpDexRuby_Zapdos[] = _("ZAPDOS is a legendary bird MOéMON that has the ability to control electricity. It usually lives in thunderclouds. The MOéMON gains power if it is stricken by lightning bolts.");
static const u8 sMpDexFireRed_Zapdos[] = _("One of the legendary bird MOéMON. While it is flying, it makes crackling and snapping sounds.");
static const u8 sMpDexRuby_Moltres[] = _("MOLTRES is a legendary bird MOéMON that has the ability to control fire. If this MOéMON is injured, it is said to dip its body in the molten magma of a volcano to burn and heal itself.");
static const u8 sMpDexFireRed_Moltres[] = _("One of the legendary bird MOéMON. Those seeing it are overwhelmed by its orange wings that seem to be on fire.");
static const u8 sMpDexRuby_Dratini[] = _("DRATINI continually molts and sloughs off its old skin. It does so because the life energy within its body steadily builds to reach uncontrollable levels.");
static const u8 sMpDexFireRed_Dratini[] = _("Even the young can exceed 6.5 feet in length. It grows larger by repeatedly shedding skin.");
static const u8 sMpDexRuby_Dragonair[] = _("DRAGONAIR stores an enormous amount of energy inside its body. It is said to alter weather conditions in its vicinity by discharging energy from the crystals on its neck and tail.");
static const u8 sMpDexFireRed_Dragonair[] = _("It is said to live in seas and lakes. Even though it has no wings, it has been seen flying occasionally.");
static const u8 sMpDexRuby_Dragonite[] = _("DRAGONITE is capable of circling the globe in just sixteen hours. It is a kindhearted MOéMON that leads lost and foundering ships in a storm to the safety of land.");
static const u8 sMpDexFireRed_Dragonite[] = _("It can fly in spite of its big and bulky physique. It circles the globe in just 16 hours.");
static const u8 sMpDexRuby_Mewtwo[] = _("MEWTWO is a MOéMON that was created by genetic manipulation. However, even though the scientific power of humans created this MOéMON's body, they failed to endow MEWTWO with a compassionate heart.");
static const u8 sMpDexFireRed_Mewtwo[] = _("A MOéMON whose genetic code was repeatedly recombined for research. It turned vicious as a result.");
static const u8 sMpDexRuby_Mew[] = _("MEW is said to possess the genetic composition of all MOéMON. It is capable of making itself invisible at will, so it entirely avoids notice even if it approaches people.");
static const u8 sMpDexFireRed_Mew[] = _("A MOéMON of South America that was thought to have been extinct. It is very intelligent and learns any move.");
static const u8 sMpDexRuby_Chikorita[] = _("In battle, CHIKORITA waves its leaf around to keep the foe at bay. However, a sweet fragrance also wafts from the leaf, becalming the battling MOéMON and creating a cozy, friendly atmosphere all around.");
static const u8 sMpDexFireRed_Chikorita[] = _("Its pleasantly aromatic leaf has the ability to check the humidity and temperature.");
static const u8 sMpDexRuby_Bayleef[] = _("BAYLEEF's neck is ringed by curled-up leaves. Inside each tubular leaf is a small shoot of a tree. The fragrance of this shoot makes people peppy.");
static const u8 sMpDexFireRed_Bayleef[] = _("A spicy aroma emanates from around its neck. The aroma acts as a stimulant to restore health.");
static const u8 sMpDexRuby_Meganium[] = _("The fragrance of MEGANIUM's flower soothes and calms emotions. In battle, this MOéMON gives off more of its becalming scent to blunt the foe's fighting spirit.");
static const u8 sMpDexFireRed_Meganium[] = _("MEGANIUM's breath has the power to revive dead grass and plants. It can make them healthy again.");
static const u8 sMpDexRuby_Cyndaquil[] = _("CYNDAQUIL protects itself by flaring up the flames on its back. The flames are vigorous if the MOéMON is angry. However, if it is tired, the flames splutter fitfully with incomplete combustion.");
static const u8 sMpDexFireRed_Cyndaquil[] = _("It usually stays hunched over. If it is angry or surprised, it shoots flames out of its back.");
static const u8 sMpDexRuby_Quilava[] = _("QUILAVA keeps its foes at bay with the intensity of its flames and gusts of superheated air. This MOéMON applies its outstanding nimbleness to dodge attacks even while scorching the foe with flames.");
static const u8 sMpDexFireRed_Quilava[] = _("This MOéMON is fully covered by nonflammable fur. It can withstand any kind of fire attack.");
static const u8 sMpDexRuby_Typhlosion[] = _("TYPHLOSION obscures itself behind a shimmering heat haze that it creates using its intensely hot flames. This MOéMON creates blazing explosive blasts that burn everything to cinders.");
static const u8 sMpDexFireRed_Typhlosion[] = _("It has a secret, devastating move. It rubs its blazing fur together to cause huge explosions.");
static const u8 sMpDexRuby_Totodile[] = _("Despite the smallness of its body, TOTODILE's jaws are very powerful. While the MOéMON may think it is just playfully nipping, its bite has enough power to cause serious injury.");
static const u8 sMpDexFireRed_Totodile[] = _("It is small but rough and tough. It won't hesitate to take a bite out of anything that moves.");
static const u8 sMpDexRuby_Croconaw[] = _("Once CROCONAW has clamped its jaws on its foe, it will absolutely not let go. Because the tips of its fangs are forked back like barbed fishhooks, they become impossible to remove when they have sunk in.");
static const u8 sMpDexFireRed_Croconaw[] = _("It opens its huge jaws wide when attacking. If it loses any fangs while biting, they grow back in.");
static const u8 sMpDexRuby_Feraligatr[] = _("FERALIGATR intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed.");
static const u8 sMpDexFireRed_Feraligatr[] = _("It is hard for it to support its own weight out of water, so it gets down on all fours. But it moves fast.");
static const u8 sMpDexRuby_Sentret[] = _("When SENTRET sleeps, it does so while another stands guard. The sentry wakes the others at the first sign of danger. When this MOéMON becomes separated from its pack, it becomes incapable of sleep due to fear.");
static const u8 sMpDexFireRed_Sentret[] = _("It stands on its tail so it can see a long way. If it spots an enemy, it cries loudly to warn its kind.");
static const u8 sMpDexRuby_Furret[] = _("FURRET has a very slim build. When under attack, it can slickly squirm through narrow spaces and get away. In spite of its short limbs, this MOéMON is very nimble and fleet.");
static const u8 sMpDexFireRed_Furret[] = _("There is no telling where its tail begins. Despite its short legs, it is quick at hunting RATTATA.");
static const u8 sMpDexRuby_Hoothoot[] = _("HOOTHOOT has an internal organ that senses and tracks the earth's rotation. Using this special organ, this MOéMON begins hooting at precisely the same time every day.");
static const u8 sMpDexFireRed_Hoothoot[] = _("It has a perfect sense of time. Whatever happens, it keeps rhythm by precisely tilting its head in time.");
static const u8 sMpDexRuby_Noctowl[] = _("NOCTOWL never fails at catching prey in darkness. This MOéMON owes its success to its superior vision that allows it to see in minimal light, and to its soft, supple wings that make no sound in flight.");
static const u8 sMpDexFireRed_Noctowl[] = _("When it needs to think, it rotates its head 180 degrees to sharpen its intellectual power.");
static const u8 sMpDexRuby_Ledyba[] = _("LEDYBA secretes an aromatic fluid from where its legs join its body. This fluid is used for communicating with others. This MOéMON conveys its feelings to others by altering the fluid's scent.");
static const u8 sMpDexFireRed_Ledyba[] = _("When the weather turns cold, numerous LEDYBA gather from everywhere to cluster and keep each other warm.");
static const u8 sMpDexRuby_Ledian[] = _("It is said that in lands with clean air, where the stars fill the sky, there live LEDIAN in countless numbers. There is a good reason for this - the MOéMON uses the light of the stars as its energy.");
static const u8 sMpDexFireRed_Ledian[] = _("The star patterns on its back grow larger or smaller depending on the number of stars in the night sky.");
static const u8 sMpDexRuby_Spinarak[] = _("The web spun by SPINARAK can be considered its second nervous system. It is said that this MOéMON can determine what kind of prey is touching its web just by the tiny vibrations it feels through the web's strands.");
static const u8 sMpDexFireRed_Spinarak[] = _("It spins a web using fine--but durable--thread. It then waits patiently for prey to be trapped.");
static const u8 sMpDexRuby_Ariados[] = _("ARIADOS's feet are tipped with tiny hooked claws that enable it to scuttle on ceilings and vertical walls. This MOéMON constricts the foe with thin and strong silk webbing.");
static const u8 sMpDexFireRed_Ariados[] = _("A single strand of a special string is endlessly spun out of its rear. The string leads back to its nest.");
static const u8 sMpDexRuby_Crobat[] = _("If this MOéMON is flying by fluttering only a pair of wings on either the forelegs or hind legs, it's proof that CROBAT has been flying a long distance. It switches the wings it uses if it is tired.");
static const u8 sMpDexSapphire_Crobat[] = _("CROBAT sneaks up on its intended prey using wings that barely make a sound. This MOéMON rests by hanging on a tree branch with its rear legs that serve as wings.");
static const u8 sMpDexFireRed_Crobat[] = _("The development of wings on its legs enables it to fly fast but also makes it tough to stop and rest.");
static const u8 sMpDexRuby_Chinchou[] = _("CHINCHOU lets loose positive and negative electrical charges from its two antennas to make its prey faint. This MOéMON flashes its electric lights to exchange signals with others.");
static const u8 sMpDexSapphire_Chinchou[] = _("CHINCHOU's two antennas are filled with cells that generate strong electricity. This MOéMON's cells create so much electrical power, it even makes itself tingle slightly.");
static const u8 sMpDexFireRed_Chinchou[] = _("On the dark ocean floor, its only means of communication is its constantly flashing lights.");
static const u8 sMpDexRuby_Lanturn[] = _("LANTURN is nicknamed “the deep-sea star” for its illuminated antenna. This MOéMON produces light by causing a chemical reaction between bacteria and its bodily fluids inside the antenna.");
static const u8 sMpDexSapphire_Lanturn[] = _("LANTURN is known to emit light. If you peer down into the dark sea from a ship at night, you can sometimes see this MOéMON's light rising from the depths where it swims. It gives the sea an appearance of a starlit night.");
static const u8 sMpDexFireRed_Lanturn[] = _("It blinds prey with an intense burst of light, then swallows the immobilized prey in a single gulp.");
static const u8 sMpDexRuby_Pichu[] = _("PICHU charges itself with electricity more easily on days with thunderclouds or when the air is very dry. You can hear the crackling of static electricity coming off this MOéMON.");
static const u8 sMpDexSapphire_Pichu[] = _("When PICHU plays with others, it may short out electricity with another PICHU, creating a shower of sparks. In that event, this MOéMON will begin crying, startled by the flash of sparks.");
static const u8 sMpDexFireRed_Pichu[] = _("Despite its small size, it can zap even adult humans. However, if it does so, it also surprises itself.");
static const u8 sMpDexRuby_Cleffa[] = _("On nights with many shooting stars, CLEFFA can be seen dancing in a ring. They dance through the night and stop only at the break of day, when these MOéMON quench their thirst with the morning dew.");
static const u8 sMpDexFireRed_Cleffa[] = _("When numerous meteors illuminate the night sky, sightings of CLEFFA strangely increase.");
static const u8 sMpDexRuby_Igglybuff[] = _("IGGLYBUFF's vocal chords are not sufficiently developed. It would hurt its throat if it were to sing too much. This MOéMON gargles with freshwater from a clean stream.");
static const u8 sMpDexSapphire_Igglybuff[] = _("IGGLYBUFF has a soft and plushy body that feels very much like a marshmallow. From this body wafts a gently sweet fragrance that soothes and calms the emotions of its foes.");
static const u8 sMpDexFireRed_Igglybuff[] = _("Its extremely flexible and elastic body makes it bounce continuously--anytime, anywhere.");
static const u8 sMpDexRuby_Togepi[] = _("As its energy, TOGEPI uses the positive emotions of compassion and pleasure exuded by people and MOéMON. This MOéMON stores up feelings of happiness inside its shell, then shares them with others.");
static const u8 sMpDexFireRed_Togepi[] = _("A proverb claims that happiness will come to anyone who can make a sleeping TOGEPI stand up.");
static const u8 sMpDexRuby_Togetic[] = _("TOGETIC is said to be a MOéMON that brings good fortune. When the MOéMON spots someone who is pure of heart, it is said to appear and share its happiness with that person.");
static const u8 sMpDexFireRed_Togetic[] = _("It grows dispirited if it is not with kind people. It can float in midair without moving its wings.");
static const u8 sMpDexRuby_Natu[] = _("NATU cannot fly because its wings are not yet fully grown. If your eyes meet with this MOéMON's eyes, it will stare back intently at you. But if you move even slightly, it will hop away to safety.");
static const u8 sMpDexSapphire_Natu[] = _("NATU has a highly developed jumping ability. The MOéMON flaps and leaps onto tree branches that are taller than grown-up people to pick at the tree's new shoots.");
static const u8 sMpDexFireRed_Natu[] = _("It usually forages for food on the ground but may, on rare occasions, hop onto branches to peck at shoots.");
static const u8 sMpDexRuby_Xatu[] = _("XATU stands rooted and still in one spot all day long. People believe that this MOéMON does so out of fear of the terrible things it has foreseen in the future.");
static const u8 sMpDexSapphire_Xatu[] = _("XATU is known to stand motionless while staring at the sun all day long. Some people revere it as a mystical MOéMON out of their belief that XATU is in possession of the power to see into the future.");
static const u8 sMpDexFireRed_Xatu[] = _("In South America, it is said that its right eye sees the future and its left eye views the past.");
static const u8 sMpDexRuby_Mareep[] = _("MAREEP's fluffy coat of wool rubs together and builds a static charge. The more static electricity is charged, the more brightly the lightbulb at the tip of its tail grows.");
static const u8 sMpDexFireRed_Mareep[] = _("Its fleece grows continually. In the summer, the fleece is fully shed, but it grows back in a week.");
static const u8 sMpDexRuby_Flaaffy[] = _("FLAAFFY's wool quality changes so that it can generate a high amount of static electricity with a small amount of wool. The bare and slick parts of its hide are shielded against electricity.");
static const u8 sMpDexFireRed_Flaaffy[] = _("Its fluffy fleece easily stores electricity. Its rubbery hide keeps it from being electrocuted.");
static const u8 sMpDexRuby_Ampharos[] = _("AMPHAROS gives off so much light that it can be seen even from space. People in the old days used the light of this MOéMON to send signals back and forth with others far away.");
static const u8 sMpDexFireRed_Ampharos[] = _("The bright light on its tail can be seen far away. It has been treasured since ancient times as a beacon.");
static const u8 sMpDexRuby_Bellossom[] = _("When BELLOSSOM gets exposed to plenty of sunlight, the leaves ringing its body begin to spin around. This MOéMON's dancing is renowned in the southern lands.");
static const u8 sMpDexSapphire_Bellossom[] = _("A BELLOSSOM grows flowers more beautifully if it has evolved from a smelly GLOOM - the stinkier the better. At night, this MOéMON closes its petals and goes to sleep.");
static const u8 sMpDexFireRed_Bellossom[] = _("Plentiful in the tropics. When it dances, its petals rub together and make a pleasant ringing sound.");
static const u8 sMpDexRuby_Marill[] = _("MARILL's oil-filled tail acts much like a life preserver. If you see just its tail bobbing on the water's surface, it's a sure indication that this MOéMON is diving beneath the water to feed on aquatic plants.");
static const u8 sMpDexSapphire_Marill[] = _("When fishing for food at the edge of a fast-running stream, MARILL wraps its tail around the trunk of a tree. This MOéMON's tail is flexible and configured to stretch.");
static const u8 sMpDexFireRed_Marill[] = _("The end of its tail serves as a buoy that keeps it from drowning, even in a vicious current.");
static const u8 sMpDexRuby_Azumarill[] = _("AZUMARILL's long ears are indispensable sensors. By focusing its hearing, this MOéMON can identify what kinds of prey are around, even in rough and fast-running rivers.");
static const u8 sMpDexSapphire_Azumarill[] = _("AZUMARILL can make balloons out of air. It makes these air balloons if it spots a drowning MOéMON. The air balloons enable the MOéMON in trouble to breathe.");
static const u8 sMpDexFireRed_Azumarill[] = _("When it plays in water, it rolls up its elongated ears to prevent their insides from getting wet.");
static const u8 sMpDexRuby_Sudowoodo[] = _("SUDOWOODO camouflages itself as a tree to avoid being attacked by enemies. However, because the forelegs remain green throughout the year, the MOéMON is easily identified as a fake during the winter.");
static const u8 sMpDexFireRed_Sudowoodo[] = _("It disguises itself as a tree to avoid attack. It hates water, so it will disappear if it starts raining.");
static const u8 sMpDexRuby_Politoed[] = _("The curled hair on POLITOED's head is proof of its status as a king. It is said that the longer and more curled the hair, the more respect this MOéMON earns from its peers.");
static const u8 sMpDexFireRed_Politoed[] = _("Whenever three or more of these get together, they sing in a loud voice that sounds like bellowing.");
static const u8 sMpDexRuby_Hoppip[] = _("This MOéMON drifts and floats with the wind. If it senses the approach of strong winds, HOPPIP links its leaves with other HOPPIP to prepare against being blown away.");
static const u8 sMpDexFireRed_Hoppip[] = _("Its body is so light, it must grip the ground firmly with its feet to keep from being blown away.");
static const u8 sMpDexRuby_Skiploom[] = _("SKIPLOOM's flower blossoms when the temperature rises above 64 degrees F. How much the flower opens depends on the temperature. For that reason, this MOéMON is sometimes used as a thermometer.");
static const u8 sMpDexFireRed_Skiploom[] = _("It spreads its petals to absorb sunlight. It also floats in the air to get closer to the sun.");
static const u8 sMpDexRuby_Jumpluff[] = _("JUMPLUFF rides warm southern winds to cross the sea and fly to foreign lands. The MOéMON descends to the ground when it encounters cold air while it is floating.");
static const u8 sMpDexFireRed_Jumpluff[] = _("It drifts on seasonal winds and spreads its cotton-like spores all over the world to make more offspring.");
static const u8 sMpDexRuby_Aipom[] = _("AIPOM's tail ends in a hand-like appendage that can be cleverly manipulated. However, because the MOéMON uses its tail so much, its real hands have become rather clumsy.");
static const u8 sMpDexFireRed_Aipom[] = _("It lives atop tall trees. When leaping from branch to branch, it deftly uses its tail for balance.");
static const u8 sMpDexRuby_Sunkern[] = _("SUNKERN tries to move as little as it possibly can. It does so because it tries to conserve all the nutrients it has stored in its body for its evolution. It will not eat a thing, subsisting only on morning dew.");
static const u8 sMpDexFireRed_Sunkern[] = _("It lives by drinking only dewdrops from under the leaves of plants. It is said that it eats nothing else.");
static const u8 sMpDexRuby_Sunflora[] = _("SUNFLORA converts solar energy into nutrition. It moves around actively in the daytime when it is warm. It stops moving as soon as the sun goes down for the night.");
static const u8 sMpDexFireRed_Sunflora[] = _("In the daytime, it rushes about in a hectic manner, but it comes to a complete stop when the sun sets.");
static const u8 sMpDexRuby_Yanma[] = _("YANMA is capable of seeing 360 degrees without having to move its eyes. It is a great flier that is adept at making sudden stops and turning midair. This MOéMON uses its flying ability to quickly chase down targeted prey.");
static const u8 sMpDexFireRed_Yanma[] = _("Its large eyes can scan 360 degrees. It looks in all directions to seek out insects as its prey.");
static const u8 sMpDexRuby_Wooper[] = _("WOOPER usually lives in water. However, it occasionally comes out onto land in search of food. On land, it coats its body with a gooey, toxic film.");
static const u8 sMpDexFireRed_Wooper[] = _("When it walks around on the ground, it coats its body with a slimy, poisonous film.");
static const u8 sMpDexRuby_Quagsire[] = _("QUAGSIRE hunts for food by leaving its mouth wide open in water and waiting for its prey to blunder in unaware. Because the MOéMON does not move, it does not get very hungry.");
static const u8 sMpDexFireRed_Quagsire[] = _("Due to its relaxed and carefree attitude, it often bumps its head on boulders and boat hulls as it swims.");
static const u8 sMpDexRuby_Espeon[] = _("ESPEON is extremely loyal to any TRAINER it considers to be worthy. It is said that this MOéMON developed its precognitive powers to protect its TRAINER from harm.");
static const u8 sMpDexFireRed_Espeon[] = _("By reading air currents, it can predict things such as the weather or its foe's next move.");
static const u8 sMpDexRuby_Umbreon[] = _("UMBREON evolved as a result of exposure to the moon's waves. It hides silently in darkness and waits for its foes to make a move. The rings on its body glow when it leaps to attack.");
static const u8 sMpDexFireRed_Umbreon[] = _("When darkness falls, the rings on its body begin to glow, striking fear in the hearts of anyone nearby.");
static const u8 sMpDexRuby_Murkrow[] = _("MURKROW was feared and loathed as the alleged bearer of ill fortune. This MOéMON shows strong interest in anything that sparkles or glitters. It will even try to steal rings from women.");
static const u8 sMpDexFireRed_Murkrow[] = _("It is said that when chased, it lures its attacker onto dark mountain trails where the foe will get lost.");
static const u8 sMpDexRuby_Slowking[] = _("SLOWKING undertakes research every day in an effort to solve the mysteries of the world. However, this MOéMON apparently forgets everything it has learned if the SHELLDER on its head comes off.");
static const u8 sMpDexFireRed_Slowking[] = _("When its head was bitten, toxins entered SLOWPOKE's head and unlocked an extraordinary power.");
static const u8 sMpDexRuby_Misdreavus[] = _("MISDREAVUS frightens people with a creepy, sobbing cry. The MOéMON apparently uses its red spheres to absorb the fearful feelings of foes and turn them into nutrition.");
static const u8 sMpDexFireRed_Misdreavus[] = _("It loves to bite and yank people's hair from behind without warning, just to see their shocked reactions.");
static const u8 sMpDexRuby_Unown[] = _("This MOéMON is shaped like ancient writing. It is a mystery as to which came first, the ancient writings or the various UNOWN. Research into this topic is ongoing but nothing is known.");
static const u8 sMpDexFireRed_Unown[] = _("Its flat, thin body is always stuck on walls. Its shape appears to have some meaning.");
static const u8 sMpDexRuby_Wobbuffet[] = _("If two or more WOBBUFFET meet, they will turn competitive and try to outdo each other's endurance. However, they may try to see which one can endure the longest without food. TRAINERS need to beware of this habit.");
static const u8 sMpDexSapphire_Wobbuffet[] = _("WOBBUFFET does nothing but endure attacks - it won't attack on its own. However, it won't endure an attack on its tail. When that happens, the MOéMON will try to take the foe with it using DESTINY BOND.");
static const u8 sMpDexFireRed_Wobbuffet[] = _("To keep its pitch-black tail hidden, it lives quietly in the darkness. It is never first to attack.");
static const u8 sMpDexRuby_Girafarig[] = _("GIRAFARIG's rear head also has a brain, but it is small. The rear head attacks in response to smells and sounds. Approaching this MOéMON from behind can cause the rear head to suddenly lash out and bite.");
static const u8 sMpDexSapphire_Girafarig[] = _("GIRAFARIG's rear head contains a tiny brain that is too small for thinking. However, the rear head doesn't need to sleep, so it can keep watch over its surroundings 24 hours a day.");
static const u8 sMpDexFireRed_Girafarig[] = _("Its tail, which also contains a small brain, may bite on its own if it notices an alluring smell.");
static const u8 sMpDexRuby_Pineco[] = _("PINECO hangs from a tree branch and patiently waits for prey to come along. If the MOéMON is disturbed while eating by someone shaking its tree, it drops down to the ground and explodes with no warning.");
static const u8 sMpDexFireRed_Pineco[] = _("It hangs and waits for flying-insect prey to come near. It does not move about much on its own.");
static const u8 sMpDexRuby_Forretress[] = _("FORRETRESS conceals itself inside its hardened steel shell. The shell is opened when the MOéMON is catching prey, but it does so at such a quick pace that the shell's inside cannot be seen.");
static const u8 sMpDexFireRed_Forretress[] = _("It remains immovably rooted to its tree. It scatters pieces of its hard shell to drive its enemies away.");
static const u8 sMpDexRuby_Dunsparce[] = _("DUNSPARCE has a drill for its tail. It uses this tail to burrow into the ground backwards. This MOéMON is known to make its nest in complex shapes deep under the ground.");
static const u8 sMpDexFireRed_Dunsparce[] = _("If spotted, it escapes by burrowing with its tail. It can hover just slightly using its wings.");
static const u8 sMpDexRuby_Gligar[] = _("GLIGAR glides through the air without a sound as if it were sliding. This MOéMON hangs on to the face of its foe using its clawed hind legs and the large pincers on its forelegs, then injects the prey with its poison barb.");
static const u8 sMpDexFireRed_Gligar[] = _("It usually clings to cliffs. When it spots its prey, it spreads its wings and glides down to attack.");
static const u8 sMpDexRuby_Steelix[] = _("STEELIX lives even further underground than ONIX. This MOéMON is known to dig towards the earth's core. There are records of this MOéMON reaching a depth of over six-tenths of a mile underground.");
static const u8 sMpDexFireRed_Steelix[] = _("It is said that if an ONIX lives for over 100 years, its composition changes to become diamond-like.");
static const u8 sMpDexRuby_Snubbull[] = _("By baring its fangs and making a scary face, SNUBBULL sends smaller MOéMON scurrying away in terror. However, this MOéMON seems a little sad at making its foes flee.");
static const u8 sMpDexFireRed_Snubbull[] = _("It has an active, playful nature. Many women like to frolic with it because of its affectionate ways.");
static const u8 sMpDexRuby_Granbull[] = _("GRANBULL has a particularly well-developed lower jaw. The enormous fangs are heavy, causing the MOéMON to tip its head back for balance. Unless it is startled, it will not try to bite indiscriminately.");
static const u8 sMpDexFireRed_Granbull[] = _("Because its fangs are too heavy, it always keeps its head tilted down. However, its BITE is powerful.");
static const u8 sMpDexRuby_Qwilfish[] = _("QWILFISH sucks in water, inflating itself. This MOéMON uses the pressure of the water it swallowed to shoot toxic quills all at once from all over its body. It finds swimming somewhat challenging.");
static const u8 sMpDexFireRed_Qwilfish[] = _("The small spikes covering its body developed from scales. They inject a toxin that causes fainting.");
static const u8 sMpDexRuby_Scizor[] = _("SCIZOR has a body with the hardness of steel. It is not easily fazed by ordinary sorts of attacks. This MOéMON flaps its wings to regulate its body temperature.");
static const u8 sMpDexFireRed_Scizor[] = _("Its wings are not used for flying. They are flapped at high speed to adjust its body temperature.");
static const u8 sMpDexRuby_Shuckle[] = _("SHUCKLE quietly hides itself under rocks, keeping its body concealed inside its hard shell while eating berries it has stored away. The berries mix with its body fluids to become a juice.");
static const u8 sMpDexFireRed_Shuckle[] = _("It stores BERRIES inside its shell. To avoid attacks, it hides beneath rocks and remains completely still.");
static const u8 sMpDexRuby_Heracross[] = _("HERACROSS charges in a straight line at its foe, slips beneath the foe's grasp, and then scoops up and hurls the opponent with its mighty horn. This MOéMON even has enough power to topple a massive tree.");
static const u8 sMpDexSapphire_Heracross[] = _("HERACROSS has sharp claws on its feet. These are planted firmly into the ground or the bark of a tree, giving the MOéMON a secure and solid footing to forcefully fling away foes with its proud horn.");
static const u8 sMpDexFireRed_Heracross[] = _("Usually docile, but if disturbed while sipping honey, it chases off the intruder with its horn.");
static const u8 sMpDexRuby_Sneasel[] = _("SNEASEL scales trees by punching its hooked claws into the bark. This MOéMON seeks out unguarded nests and steals eggs for food while the parents are away.");
static const u8 sMpDexFireRed_Sneasel[] = _("Vicious in nature, it drives PIDGEY from their nests and feasts on the eggs that are left behind.");
static const u8 sMpDexRuby_Teddiursa[] = _("This MOéMON likes to lick its palms that are sweetened by being soaked in honey. TEDDIURSA concocts its own honey by blending fruits and pollen collected by BEEDRILL.");
static const u8 sMpDexFireRed_Teddiursa[] = _("Before food becomes scarce in wintertime, its habit is to hoard food in many hidden locations.");
static const u8 sMpDexRuby_Ursaring[] = _("In the forests inhabited by URSARING, it is said that there are many streams and towering trees where they gather food. This MOéMON walks through its forest gathering food every day.");
static const u8 sMpDexFireRed_Ursaring[] = _("With its ability to distinguish any smell, it unfailingly finds all food buried deep underground.");
static const u8 sMpDexRuby_Slugma[] = _("Molten magma courses throughout SLUGMA's circulatory system. If this MOéMON is chilled, the magma cools and hardens. Its body turns brittle and chunks fall off, reducing its size.");
static const u8 sMpDexSapphire_Slugma[] = _("SLUGMA does not have any blood in its body. Instead, intensely hot magma circulates throughout this MOéMON's body, carrying essential nutrients and oxygen to its organs.");
static const u8 sMpDexFireRed_Slugma[] = _("A common sight in volcanic areas, it slowly slithers around in a constant search for warm places.");
static const u8 sMpDexRuby_Magcargo[] = _("MAGCARGO's shell is actually its skin that hardened as a result of cooling. Its shell is very brittle and fragile - just touching it causes it to crumble apart. This MOéMON returns to its original size by dipping itself in magma.");
static const u8 sMpDexSapphire_Magcargo[] = _("MAGCARGO's body temperature is approximately 18,000 degrees F. Water is vaporized on contact. If this MOéMON is caught in the rain, the raindrops instantly turn into steam, cloaking the area in a thick fog.");
static const u8 sMpDexFireRed_Magcargo[] = _("Its brittle shell occasionally spouts intense flames that circulate throughout its body.");
static const u8 sMpDexRuby_Swinub[] = _("SWINUB roots for food by rubbing its snout against the ground. Its favorite food is a mushroom that grows under the cover of dead grass. This MOéMON occasionally roots out hot springs.");
static const u8 sMpDexFireRed_Swinub[] = _("If it smells something enticing, it dashes off headlong to find the source of the aroma.");
static const u8 sMpDexRuby_Piloswine[] = _("PILOSWINE is covered by a thick coat of long hair that enables it to endure the freezing cold. This MOéMON uses its tusks to dig up food that has been buried under ice.");
static const u8 sMpDexFireRed_Piloswine[] = _("If it charges at an enemy, the hairs on its back stand up straight. It is very sensitive to sound.");
static const u8 sMpDexRuby_Corsola[] = _("CORSOLA's branches glitter very beautifully in seven colors when they catch sunlight. If any branch breaks off, this MOéMON grows it back in just one night.");
static const u8 sMpDexSapphire_Corsola[] = _("Clusters of CORSOLA congregate in warm seas where they serve as ideal hiding places for smaller MOéMON. When the water temperature falls, this MOéMON migrates to the southern seas.");
static const u8 sMpDexFireRed_Corsola[] = _("In a south sea nation, the people live in communities that are built on groups of these MOéMON.");
static const u8 sMpDexRuby_Remoraid[] = _("REMORAID sucks in water, then expels it at high velocity using its abdominal muscles to shoot down flying prey. When evolution draws near, this MOéMON travels downstream from rivers.");
static const u8 sMpDexFireRed_Remoraid[] = _("Using its dorsal fin as a suction pad, it clings to a MANTINE's underside to scavenge for leftovers.");
static const u8 sMpDexRuby_Octillery[] = _("OCTILLERY grabs onto its foe using its tentacles. This MOéMON tries to immobilize it before delivering the finishing blow. If the foe turns out to be too strong, OCTILLERY spews ink to escape.");
static const u8 sMpDexFireRed_Octillery[] = _("It instinctively sneaks into rocky holes. If it gets sleepy, it steals the nest of a fellow OCTILLERY.");
static const u8 sMpDexRuby_Delibird[] = _("DELIBIRD carries its food bundled up in its tail. There once was a famous explorer who managed to reach the peak of Mt. Everest thanks to one of these MOéMON sharing its food.");
static const u8 sMpDexFireRed_Delibird[] = _("It nests at the edge of sharp cliffs. It spends all day carrying food to its awaiting chicks.");
static const u8 sMpDexRuby_Mantine[] = _("On sunny days, schools of MANTINE can be seen elegantly leaping over the sea's waves. This MOéMON is not bothered by the REMORAID that hitches rides.");
static const u8 sMpDexFireRed_Mantine[] = _("Swimming freely in open seas, it may fly out of the water and over the waves if it builds up enough speed.");
static const u8 sMpDexRuby_Skarmory[] = _("SKARMORY is entirely encased in hard, protective armor. This MOéMON flies at close to 190 mph. It slashes foes with its wings that possess swordlike cutting edges.");
static const u8 sMpDexSapphire_Skarmory[] = _("SKARMORY's steel wings become tattered and bashed in from repeated battles. Once a year, the battered wings grow back completely, restoring the cutting edges to their pristine state.");
static const u8 sMpDexFireRed_Skarmory[] = _("After nesting in bramble bushes, the wings of its chicks grow hard from scratches by thorns.");
static const u8 sMpDexRuby_Houndour[] = _("HOUNDOUR hunt as a coordinated pack. They communicate with each other using a variety of cries to corner their prey. This MOéMON's remarkable teamwork is unparalleled.");
static const u8 sMpDexFireRed_Houndour[] = _("To corner prey, they check each other's location using barks that only they can understand.");
static const u8 sMpDexRuby_Houndoom[] = _("In a HOUNDOOM pack, the one with its horns raked sharply towards the back serves a leadership role. These MOéMON choose their leader by fighting amongst themselves.");
static const u8 sMpDexFireRed_Houndoom[] = _("Upon hearing its eerie howls, other MOéMON get the shivers and head straight back to their nests.");
static const u8 sMpDexRuby_Kingdra[] = _("KINGDRA lives at extreme ocean depths that are otherwise uninhabited. It has long been believed that the yawning of this MOéMON creates spiraling ocean currents.");
static const u8 sMpDexSapphire_Kingdra[] = _("KINGDRA sleeps on the seafloor where it is otherwise devoid of life. When a storm arrives, the MOéMON is said to awaken and wander about in search of prey.");
static const u8 sMpDexFireRed_Kingdra[] = _("It sleeps deep on the ocean floor to build its energy. It is said to cause tornadoes as it wakes.");
static const u8 sMpDexRuby_Phanpy[] = _("For its nest, PHANPY digs a vertical pit in the ground at the edge of a river. It marks the area around its nest with its trunk to let the others know that the area has been claimed.");
static const u8 sMpDexSapphire_Phanpy[] = _("PHANPY uses its long nose to shower itself. When others gather around, they thoroughly douse each other with water. These MOéMON can be seen drying their soaking-wet bodies at the edge of water.");
static const u8 sMpDexFireRed_Phanpy[] = _("As a sign of affection, it bumps with its snout. However, it is so strong, it may send you flying.");
static const u8 sMpDexRuby_Donphan[] = _("DONPHAN's favorite attack is curling its body into a ball, then charging at its foe while rolling at high speed. Once it starts rolling, this MOéMON can't stop very easily.");
static const u8 sMpDexSapphire_Donphan[] = _("If DONPHAN were to tackle with its hard body, even a house could be destroyed. Using its massive strength, the MOéMON helps clear rock and mud slides that block mountain trails.");
static const u8 sMpDexFireRed_Donphan[] = _("The longer and bigger its tusks, the higher its rank in its herd. The tusks take a long time to grow.");
static const u8 sMpDexRuby_Porygon2[] = _("PORYGON2 was created by humans using the power of science. The man-made MOéMON has been endowed with artificial intelligence that enables it to learn new gestures and emotions on its own.");
static const u8 sMpDexFireRed_Porygon2[] = _("Further research enhanced its abilities. Sometimes, it may exhibit motions that were not programmed.");
static const u8 sMpDexRuby_Stantler[] = _("STANTLER's magnificent antlers were traded at high prices as works of art. As a result, this MOéMON was hunted close to extinction by those who were after the priceless antlers.");
static const u8 sMpDexFireRed_Stantler[] = _("Those who stare at its antlers will gradually lose control of their senses and be unable to stand.");
static const u8 sMpDexRuby_Smeargle[] = _("SMEARGLE marks the boundaries of its territory using a body fluid that leaks out from the tip of its tail. Over 5,000 different marks left by this MOéMON have been found.");
static const u8 sMpDexFireRed_Smeargle[] = _("Once it becomes an adult, it has a tendency to let its comrades plant footprints on its back.");
static const u8 sMpDexRuby_Tyrogue[] = _("TYROGUE becomes stressed out if it does not get to train every day. When raising this MOéMON, the TRAINER must establish and uphold various training methods.");
static const u8 sMpDexFireRed_Tyrogue[] = _("Even though it is small, it can't be ignored because it will slug any handy target without warning.");
static const u8 sMpDexRuby_Hitmontop[] = _("HITMONTOP spins on its head at high speed, all the while delivering kicks. This technique is a remarkable mix of both offense and defense at the same time. The MOéMON travels faster spinning than it does walking.");
static const u8 sMpDexFireRed_Hitmontop[] = _("It launches kicks while spinning. If it spins at high speed, it may bore its way into the ground.");
static const u8 sMpDexRuby_Smoochum[] = _("SMOOCHUM actively runs about, but also falls quite often. Whenever the chance arrives, it will look for its reflection to make sure its face hasn't become dirty.");
static const u8 sMpDexFireRed_Smoochum[] = _("It always rocks its head slowly backwards and forwards as if it is trying to kiss someone.");
static const u8 sMpDexRuby_Elekid[] = _("ELEKID stores electricity in its body. If it touches metal and accidentally discharges all its built-up electricity, this MOéMON begins swinging its arms in circles to recharge itself.");
static const u8 sMpDexFireRed_Elekid[] = _("Even in the most vicious storm, this MOéMON plays happily if thunder rumbles in the sky.");
static const u8 sMpDexRuby_Magby[] = _("MAGBY's state of health is determined by observing the fire it breathes. If the MOéMON is spouting yellow flames from its mouth, it is in good health. When it is fatigued, black smoke will be mixed in with the flames.");
static const u8 sMpDexFireRed_Magby[] = _("It is found in volcanic craters. Its body heat exceeds 1,100 degrees Fahrenheit, so don't underestimate it.");
static const u8 sMpDexRuby_Miltank[] = _("MILTANK gives over five gallons of milk on a daily basis. Its sweet milk is enjoyed by children and grown-ups alike. People who can't drink milk turn it into yogurt and eat it instead.");
static const u8 sMpDexFireRed_Miltank[] = _("If it has just had a baby, the milk it produces contains much more nutrition than usual.");
static const u8 sMpDexRuby_Blissey[] = _("BLISSEY senses sadness with its fluffy coat of fur. If it does so, this MOéMON will rush over to the sad person, however far they may be, to share an egg of happiness that brings a smile to any face.");
static const u8 sMpDexFireRed_Blissey[] = _("It has a very compassionate nature. If it sees a sick MOéMON, it will nurse the sufferer back to health.");
static const u8 sMpDexRuby_Raikou[] = _("RAIKOU embodies the speed of lightning. The roars of this MOéMON send shock waves shuddering through the air and shake the ground as if lightning bolts had come crashing down.");
static const u8 sMpDexFireRed_Raikou[] = _("This MOéMON races across the land while barking a cry that sounds like crashing thunder.");
static const u8 sMpDexRuby_Entei[] = _("ENTEI embodies the passion of magma. This MOéMON is thought to have been born in the eruption of a volcano. It sends up massive bursts of fire that utterly consume all that they touch.");
static const u8 sMpDexFireRed_Entei[] = _("A MOéMON that races across the land. It is said that one is born every time a new volcano appears.");
static const u8 sMpDexRuby_Suicune[] = _("SUICUNE embodies the compassion of a pure spring of water. It runs across the land with gracefulness. This MOéMON has the power to purify dirty water.");
static const u8 sMpDexFireRed_Suicune[] = _("This MOéMON races across the land. It is said that north winds will somehow blow whenever it appears.");
static const u8 sMpDexRuby_Larvitar[] = _("LARVITAR is born deep under the ground. To come up to the surface, this MOéMON must eat its way through the soil above. Until it does so, LARVITAR cannot see its parent's face.");
static const u8 sMpDexFireRed_Larvitar[] = _("It is born deep underground. It can't emerge until it has entirely consumed the soil around it.");
static const u8 sMpDexRuby_Pupitar[] = _("PUPITAR creates a gas inside its body that it compresses and forcefully ejects to propel itself like a jet. The body is very durable - it avoids damage even if it hits solid steel.");
static const u8 sMpDexFireRed_Pupitar[] = _("Even sealed in its shell, it can move freely. Hard and fast, it has outstanding destructive power.");
static const u8 sMpDexRuby_Tyranitar[] = _("TYRANITAR is so overwhelmingly powerful, it can bring down a whole mountain to make its nest. This MOéMON wanders about in mountains seeking new opponents to fight.");
static const u8 sMpDexFireRed_Tyranitar[] = _("It has an impudent nature. Having great strength, it can even change surrounding landforms.");
static const u8 sMpDexRuby_Lugia[] = _("LUGIA's wings pack devastating power - a light fluttering of its wings can blow apart regular houses. As a result, this MOéMON chooses to live out of sight deep under the sea.");
static const u8 sMpDexFireRed_Lugia[] = _("It is said to be the guardian of the seas. It is rumored to have been seen on the night of a storm.");
static const u8 sMpDexRuby_HoOh[] = _("HO-OH's feathers glow in seven colors depending on the angle at which they are struck by light. These feathers are said to bring happiness to the bearers. This MOéMON is said to live at the foot of a rainbow.");
static const u8 sMpDexFireRed_HoOh[] = _("A legend says that its body glows in seven colors. A rainbow is said to form behind it when it flies.");
static const u8 sMpDexRuby_Celebi[] = _("This MOéMON came from the future by crossing over time. It is thought that so long as CELEBI appears, a bright and shining future awaits us.");
static const u8 sMpDexFireRed_Celebi[] = _("When CELEBI disappears deep in a forest, it is said to leave behind an egg it brought from the future.");
static const u8 sMpDexRuby_Treecko[] = _("TREECKO has small hooks on the bottom of its feet that enable it to scale vertical walls. This MOéMON attacks by slamming foes with its thick tail.");
static const u8 sMpDexSapphire_Treecko[] = _("TREECKO is cool, calm, and collected - it never panics under any situation. If a bigger foe were to glare at this MOéMON, it would glare right back without conceding an inch of ground.");
static const u8 sMpDexFireRed_Treecko[] = _("It quickly scales even vertical walls. It senses humidity with its tail to predict the next day's weather.");
static const u8 sMpDexRuby_Grovyle[] = _("The leaves growing out of GROVYLE's body are convenient for camouflaging it from enemies in the forest. This MOéMON is a master at climbing trees in jungles.");
static const u8 sMpDexSapphire_Grovyle[] = _("This MOéMON adeptly flies from branch to branch in trees. In a forest, no MOéMON can ever hope to catch a fleeing GROVYLE however fast they may be.");
static const u8 sMpDexFireRed_Grovyle[] = _("Its strongly developed thigh muscles give it astounding agility and jumping performance.");
static const u8 sMpDexRuby_Sceptile[] = _("The leaves growing on SCEPTILE's body are very sharp edged. This MOéMON is very agile - it leaps all over the branches of trees and jumps on its foe from above or behind.");
static const u8 sMpDexSapphire_Sceptile[] = _("SCEPTILE has seeds growing on its back. They are said to be bursting with nutrients that revitalize trees. This MOéMON raises the trees in a forest with loving care.");
static const u8 sMpDexFireRed_Sceptile[] = _("The leaves on its forelegs are as sharp as swords. It agilely leaps about the branches of trees to strike.");
static const u8 sMpDexRuby_Torchic[] = _("TORCHIC sticks with its TRAINER, following behind with unsteady steps. This MOéMON breathes fire of over 1,800 degrees F, including fireballs that leave the foe scorched black.");
static const u8 sMpDexSapphire_Torchic[] = _("TORCHIC has a place inside its body where it keeps its flame. Give it a hug - it will be glowing with warmth. This MOéMON is covered all over by a fluffy coat of down.");
static const u8 sMpDexFireRed_Torchic[] = _("It has a flame sac inside its belly that perpetually burns. It feels warm if it is hugged.");
static const u8 sMpDexRuby_Combusken[] = _("COMBUSKEN toughens up its legs and thighs by running through fields and mountains. This MOéMON's legs possess both speed and power, enabling it to dole out ten kicks in one second.");
static const u8 sMpDexSapphire_Combusken[] = _("COMBUSKEN battles with the intensely hot flames it spews from its beak and with outstandingly destructive kicks. This MOéMON's cry is very loud and distracting.");
static const u8 sMpDexFireRed_Combusken[] = _("It boosts its concentration by emitting harsh cries. Its kicks have outstanding destructive power.");
static const u8 sMpDexRuby_Blaziken[] = _("In battle, BLAZIKEN blows out intense flames from its wrists and attacks foes courageously. The stronger the foe, the more intensely this MOéMON's wrists burn.");
static const u8 sMpDexSapphire_Blaziken[] = _("BLAZIKEN has incredibly strong legs - it can easily clear a 30-story building in one leap. This MOéMON's blazing punches leave its foes scorched and blackened.");
static const u8 sMpDexFireRed_Blaziken[] = _("When facing a tough foe, it looses flames from its wrists. Its powerful legs let it jump clear over buildings.");
static const u8 sMpDexRuby_Mudkip[] = _("The fin on MUDKIP's head acts as highly sensitive radar. Using this fin to sense movements of water and air, this MOéMON can determine what is taking place around it without using its eyes.");
static const u8 sMpDexSapphire_Mudkip[] = _("In water, MUDKIP breathes using the gills on its cheeks. If it is faced with a tight situation in battle, this MOéMON will unleash its amazing power - it can crush rocks bigger than itself.");
static const u8 sMpDexFireRed_Mudkip[] = _("Its large tail fin propels it through water with powerful acceleration. It is strong in spite of its size.");
static const u8 sMpDexRuby_Marshtomp[] = _("The surface of MARSHTOMP's body is enveloped by a thin, sticky film that enables it to live on land. This MOéMON plays in mud on beaches when the ocean tide is low.");
static const u8 sMpDexSapphire_Marshtomp[] = _("MARSHTOMP is much faster at traveling through mud than it is at swimming. This MOéMON's hindquarters exhibit obvious development, giving it the ability to walk on just its hind legs.");
static const u8 sMpDexFireRed_Marshtomp[] = _("It is at its best when on muddy ground with poor footing. It quickly overwhelms foes struggling in mud.");
static const u8 sMpDexRuby_Swampert[] = _("SWAMPERT is very strong. It has enough power to easily drag a boulder weighing more than a ton. This MOéMON also has powerful vision that lets it see even in murky water.");
static const u8 sMpDexSapphire_Swampert[] = _("SWAMPERT predicts storms by sensing subtle differences in the sounds of waves and tidal winds with its fins. If a storm is approaching, it piles up boulders to protect itself.");
static const u8 sMpDexFireRed_Swampert[] = _("Its arms are rock-hard. With one swing, they can batter down its foe. It makes its nest on beautiful beaches.");
static const u8 sMpDexRuby_Poochyena[] = _("At first sight, POOCHYENA takes a bite at anything that moves. This MOéMON chases after prey until the victim becomes exhausted. However, it may turn tail if the prey strikes back.");
static const u8 sMpDexSapphire_Poochyena[] = _("POOCHYENA is an omnivore - it will eat anything. A distinguishing feature is how large its fangs are compared to its body. This MOéMON tries to intimidate its foes by making the hair on its tail bristle out.");
static const u8 sMpDexFireRed_Poochyena[] = _("It has a very tenacious nature. Its acute sense of smell lets it chase a chosen prey without ever losing track.");
static const u8 sMpDexRuby_Mightyena[] = _("MIGHTYENA gives obvious signals when it is preparing to attack. It starts to growl deeply and then flattens its body. This MOéMON will bite savagely with its sharply pointed fangs.");
static const u8 sMpDexSapphire_Mightyena[] = _("MIGHTYENA travel and act as a pack in the wild. The memory of its life in the wild compels the MOéMON to obey only those TRAINERS that it recognizes to possess superior skill.");
static const u8 sMpDexFireRed_Mightyena[] = _("It will always obey the commands of a skilled TRAINER. Its behavior arises from its living in packs in ancient times.");
static const u8 sMpDexRuby_Zigzagoon[] = _("ZIGZAGOON restlessly wanders everywhere at all times. This MOéMON does so because it is very curious. It becomes interested in anything that it happens to see.");
static const u8 sMpDexSapphire_Zigzagoon[] = _("The hair on ZIGZAGOON's back is bristly. It rubs the hard back hair against trees to leave its territorial markings. This MOéMON may play dead to fool foes in battle.");
static const u8 sMpDexFireRed_Zigzagoon[] = _("A MOéMON with abundant curiosity. It shows an interest in everything, so it always zigs and zags.");
static const u8 sMpDexRuby_Linoone[] = _("LINOONE always runs full speed and only in straight lines. If facing an obstacle, it makes a right-angle turn to evade it. This MOéMON is very challenged by gently curving roads.");
static const u8 sMpDexSapphire_Linoone[] = _("When hunting, LINOONE will make a beeline straight for the prey at a full run. While this MOéMON is capable of topping 60 mph, it has to come to a screeching halt before it can turn.");
static const u8 sMpDexFireRed_Linoone[] = _("When running in a straight line, it can top 60 miles per hour. However, it has a tough time with curved roads.");
static const u8 sMpDexRuby_Wurmple[] = _("Using the spikes on its rear end, WURMPLE peels the bark off trees and feeds on the sap that oozes out. This MOéMON's feet are tipped with suction pads that allow it to cling to glass without slipping.");
static const u8 sMpDexSapphire_Wurmple[] = _("WURMPLE is targeted by SWELLOW as prey. This MOéMON will try to resist by pointing the spikes on its rear at the attacking predator. It will weaken the foe by leaking poison from the spikes.");
static const u8 sMpDexFireRed_Wurmple[] = _("It lives amidst tall grass and in forests. When attacked, it resists by pointing its venomous spikes at the foe.");
static const u8 sMpDexRuby_Silcoon[] = _("SILCOON tethers itself to a tree branch using silk to keep from falling. There, this MOéMON hangs quietly while it awaits evolution. It peers out of the silk cocoon through a small hole.");
static const u8 sMpDexSapphire_Silcoon[] = _("SILCOON was thought to endure hunger and not consume anything before its evolution. However, it is now thought that this MOéMON slakes its thirst by drinking rainwater that collects on its silk.");
static const u8 sMpDexFireRed_Silcoon[] = _("It conserves its energy by moving as little as possible. It awaits evolution while drinking only a little rainwater.");
static const u8 sMpDexRuby_Beautifly[] = _("BEAUTIFLY's favorite food is the sweet pollen of flowers. If you want to see this MOéMON, just leave a potted flower by an open window. BEAUTIFLY is sure to come looking for pollen.");
static const u8 sMpDexSapphire_Beautifly[] = _("BEAUTIFLY has a long mouth like a coiled needle, which is very convenient for collecting pollen from flowers. This MOéMON rides the spring winds as it flits around gathering pollen.");
static const u8 sMpDexFireRed_Beautifly[] = _("Despite its appearance, it has an aggressive nature. It attacks by jabbing with its long, thin mouth.");
static const u8 sMpDexRuby_Cascoon[] = _("CASCOON makes its protective cocoon by wrapping its body entirely with a fine silk from its mouth. Once the silk goes around its body, it hardens. This MOéMON prepares for its evolution inside the cocoon.");
static const u8 sMpDexSapphire_Cascoon[] = _("If it is attacked, CASCOON remains motionless however badly it may be hurt. It does so because if it were to move, its body would be weak upon evolution. This MOéMON will also not forget the pain it endured.");
static const u8 sMpDexFireRed_Cascoon[] = _("Its body, which is made of soft silk, hardens over time. When cracks appear, evolution is near.");
static const u8 sMpDexRuby_Dustox[] = _("DUSTOX is instinctively drawn to light. Swarms of this MOéMON are attracted by the bright lights of cities, where they wreak havoc by stripping the leaves off roadside trees for food.");
static const u8 sMpDexSapphire_Dustox[] = _("When DUSTOX flaps its wings, a fine dust is scattered all over. This dust is actually a powerful poison that will even make a pro wrestler sick. This MOéMON searches for food using its antennae like radar.");
static const u8 sMpDexFireRed_Dustox[] = _("It scatters horribly toxic dust when it senses danger. They tend to gather in the glow of streetlamps at night.");
static const u8 sMpDexRuby_Lotad[] = _("LOTAD live in ponds and lakes, where they float on the surface. It grows weak if its broad leaf dies. On rare occasions, this MOéMON travels on land in search of clean water.");
static const u8 sMpDexSapphire_Lotad[] = _("LOTAD is said to have dwelled on land before. However, this MOéMON is thought to have returned to water because the leaf on its head grew large and heavy. It now lives by floating atop the water.");
static const u8 sMpDexFireRed_Lotad[] = _("It searches about for clean water. If it does not drink water for too long, the leaf on its head wilts.");
static const u8 sMpDexRuby_Lombre[] = _("LOMBRE is nocturnal - it will get active after dusk. It is also a mischief-maker. When this MOéMON spots anglers, it tugs on their fishing lines from beneath the surface and enjoys their consternation.");
static const u8 sMpDexSapphire_Lombre[] = _("LOMBRE's entire body is covered by a slippery, slimy film. It feels horribly unpleasant to be touched by this MOéMON's hands. LOMBRE is often mistaken for a human child.");
static const u8 sMpDexFireRed_Lombre[] = _("It lives at the water's edge where it is sunny. It sleeps on a bed of water grass by day and becomes active at night.");
static const u8 sMpDexRuby_Ludicolo[] = _("LUDICOLO begins dancing as soon as it hears cheerful, festive music. This MOéMON is said to appear when it hears the singing of children on hiking outings.");
static const u8 sMpDexSapphire_Ludicolo[] = _("Upon hearing an upbeat and cheerful rhythm, the cells in LUDICOLO's body become very energetic and active. Even in battle, this MOéMON will exhibit an amazing amount of power.");
static const u8 sMpDexFireRed_Ludicolo[] = _("The rhythm of bright, festive music activates LUDICOLO's cells, making it more powerful.");
static const u8 sMpDexRuby_Seedot[] = _("SEEDOT attaches itself to a tree branch using the top of its head. It sucks moisture from the tree while hanging off the branch. The more water it drinks, the glossier this MOéMON's body becomes.");
static const u8 sMpDexSapphire_Seedot[] = _("SEEDOT looks exactly like an acorn when it is dangling from a tree branch. It startles other MOéMON by suddenly moving. This MOéMON polishes its body once a day using leaves.");
static const u8 sMpDexFireRed_Seedot[] = _("If it remains still, it becomes impossible to distinguish from real nuts. It delights in surprising foraging PIDGEY.");
static const u8 sMpDexRuby_Nuzleaf[] = _("NUZLEAF live in densely overgrown forests. They occasionally venture out of the forest to startle people. This MOéMON dislikes having its long nose pinched.");
static const u8 sMpDexSapphire_Nuzleaf[] = _("This MOéMON pulls out the leaf on its head and makes a flute with it. The sound of NUZLEAF's flute strikes fear and uncertainty in the hearts of people lost in a forest.");
static const u8 sMpDexFireRed_Nuzleaf[] = _("They live in holes bored in large trees. The sound of NUZLEAF's grass flute fills listeners with dread.");
static const u8 sMpDexRuby_Shiftry[] = _("SHIFTRY is a mysterious MOéMON that is said to live atop towering trees dating back over a thousand years. It creates terrific windstorms with the fans it holds.");
static const u8 sMpDexSapphire_Shiftry[] = _("SHIFTRY's large fans generate awesome gusts of wind at a speed close to 100 feet per second. The whipped-up wind blows anything away. This MOéMON chooses to live quietly deep in forests.");
static const u8 sMpDexFireRed_Shiftry[] = _("A MOéMON that was feared as a forest guardian. It can read the foe's mind and take preemptive action.");
static const u8 sMpDexRuby_Taillow[] = _("TAILLOW courageously stands its ground against foes, however strong they may be. This gutsy MOéMON will remain defiant even after a loss. On the other hand, it cries loudly if it becomes hungry.");
static const u8 sMpDexSapphire_Taillow[] = _("TAILLOW is young - it has only just left its nest. As a result, it sometimes becomes lonesome and cries at night. This MOéMON feeds on WURMPLE that live in forests.");
static const u8 sMpDexFireRed_Taillow[] = _("It dislikes cold seasons. They migrate to other lands in search of warmth, flying over 180 miles a day.");
static const u8 sMpDexRuby_Swellow[] = _("SWELLOW flies high above our heads, making graceful arcs in the sky. This MOéMON dives at a steep angle as soon as it spots its prey. The hapless prey is tightly grasped by SWELLOW's clawed feet, preventing escape.");
static const u8 sMpDexSapphire_Swellow[] = _("SWELLOW is very conscientious about the upkeep of its glossy wings. Once two SWELLOW are gathered, they diligently take care of cleaning each other's wings.");
static const u8 sMpDexFireRed_Swellow[] = _("If its two tail feathers are standing at attention, it is proof of good health. It soars elegantly in the sky.");
static const u8 sMpDexRuby_Wingull[] = _("WINGULL has the habit of carrying prey and valuables in its beak and hiding them in all sorts of locations. This MOéMON rides the winds and flies as if it were skating across the sky.");
static const u8 sMpDexSapphire_Wingull[] = _("WINGULL rides updrafts rising from the sea by extending its long and narrow wings to glide. This MOéMON's long beak is useful for catching prey.");
static const u8 sMpDexFireRed_Wingull[] = _("It rides upon ocean winds as if it were a glider. In the winter, it hides food around its nest.");
static const u8 sMpDexRuby_Pelipper[] = _("PELIPPER is a flying transporter that carries small MOéMON and eggs inside its massive bill. This MOéMON builds its nest on steep cliffs facing the sea.");
static const u8 sMpDexSapphire_Pelipper[] = _("PELIPPER searches for food while in flight by skimming the wave tops. This MOéMON dips its large bill in the sea to scoop up food, then swallows everything in one big gulp.");
static const u8 sMpDexFireRed_Pelipper[] = _("It is a flying transporter that carries small MOéMON in its beak. It bobs on the waves to rest its wings.");
static const u8 sMpDexRuby_Ralts[] = _("RALTS senses the emotions of people using the horns on its head. This MOéMON rarely appears before people. But when it does, it draws closer if it senses that the person has a positive disposition.");
static const u8 sMpDexSapphire_Ralts[] = _("RALTS has the ability to sense the emotions of people. If its TRAINER is in a cheerful mood, this MOéMON grows cheerful and joyous in the same way.");
static const u8 sMpDexFireRed_Ralts[] = _("It is highly attuned to the emotions of people and MOéMON. It hides if it senses hostility.");
static const u8 sMpDexRuby_Kirlia[] = _("It is said that a KIRLIA that is exposed to the positive emotions of its TRAINER grows beautiful. This MOéMON controls psychokinetic powers with its highly developed brain.");
static const u8 sMpDexSapphire_Kirlia[] = _("KIRLIA uses the horns on its head to amplify its psychokinetic power. When the MOéMON uses its power, the air around it becomes distorted, creating mirages of nonexistent scenery.");
static const u8 sMpDexFireRed_Kirlia[] = _("The cheerful spirit of its TRAINER gives it energy for its psychokinetic power. It spins and dances when happy.");
static const u8 sMpDexRuby_Gardevoir[] = _("GARDEVOIR has the ability to read the future. If it senses impending danger to its TRAINER, this MOéMON is said to unleash its psychokinetic energy at full power.");
static const u8 sMpDexSapphire_Gardevoir[] = _("GARDEVOIR has the psychokinetic power to distort the dimensions and create a small black hole. This MOéMON will try to protect its TRAINER even at the risk of its own life.");
static const u8 sMpDexFireRed_Gardevoir[] = _("It has the power to predict the future. Its power peaks when it is protecting its TRAINER.");
static const u8 sMpDexRuby_Surskit[] = _("From the tips of its feet, SURSKIT secretes an oil that enables it to walk on water as if it were skating. This MOéMON feeds on microscopic organisms in ponds and lakes.");
static const u8 sMpDexSapphire_Surskit[] = _("If SURSKIT senses danger, it secretes a thick, sugary syrup from the tip of its head. There are some MOéMON that love eating this syrup.");
static const u8 sMpDexFireRed_Surskit[] = _("They usually live on ponds, but after an evening shower, they may appear on puddles in towns.");
static const u8 sMpDexRuby_Masquerain[] = _("MASQUERAIN intimidates enemies with the eyelike patterns on its antennas. This MOéMON flaps its four wings to freely fly in any direction - even sideways and backwards - as if it were a helicopter.");
static const u8 sMpDexSapphire_Masquerain[] = _("MASQUERAIN's antennas have eyelike patterns that usually give it an angry look. If the “eyes” are droopy and appear sad, it is said to be a sign that a heavy rainfall is on its way.");
static const u8 sMpDexFireRed_Masquerain[] = _("The antennae have distinctive patterns that look like eyes. When it rains, they grow heavy, making flight impossible.");
static const u8 sMpDexRuby_Shroomish[] = _("SHROOMISH live in damp soil in the dark depths of forests. They are often found keeping still under fallen leaves. This MOéMON feeds on compost that is made up of fallen, rotted leaves.");
static const u8 sMpDexSapphire_Shroomish[] = _("If SHROOMISH senses danger, it shakes its body and scatters spores from the top of its head. This MOéMON's spores are so toxic, they make trees and weeds wilt.");
static const u8 sMpDexFireRed_Shroomish[] = _("It prefers damp places. By day it remains still in the forest shade. It releases toxic powder from its head.");
static const u8 sMpDexRuby_Breloom[] = _("BRELOOM closes in on its foe with light and sprightly footwork, then throws punches with its stretchy arms. This MOéMON's fighting technique puts boxers to shame.");
static const u8 sMpDexSapphire_Breloom[] = _("The seeds ringing BRELOOM's tail are made of hardened toxic spores. It is horrible to eat the seeds. Just taking a bite of this MOéMON's seed will cause your stomach to rumble.");
static const u8 sMpDexFireRed_Breloom[] = _("The seeds on its tail are made of toxic spores. It knocks out foes with quick, virtually invisible punches.");
static const u8 sMpDexRuby_Slakoth[] = _("SLAKOTH lolls around for over twenty hours every day. Because it moves so little, it does not need much food. This MOéMON's sole daily meal consists of just three leaves.");
static const u8 sMpDexSapphire_Slakoth[] = _("SLAKOTH's heart beats just once a minute. Whatever happens, it is content to loaf around motionless. It is rare to see this MOéMON in motion.");
static const u8 sMpDexFireRed_Slakoth[] = _("It sleeps for 20 hours every day. Making drowsy those that see it is one of its abilities.");
static const u8 sMpDexRuby_Vigoroth[] = _("VIGOROTH is always itching and agitated to go on a wild rampage. It simply can't tolerate sitting still for even a minute. This MOéMON's stress level rises if it can't be moving constantly.");
static const u8 sMpDexSapphire_Vigoroth[] = _("VIGOROTH is simply incapable of remaining still. Even when it tries to sleep, the blood in its veins grows agitated, compelling this MOéMON to run wild throughout the jungle before it can settle down.");
static const u8 sMpDexFireRed_Vigoroth[] = _("It is always hungry because it won't stop rampaging. Even while it is eating, it can't keep still.");
static const u8 sMpDexRuby_Slaking[] = _("SLAKING spends all day lying down and lolling about. It eats grass growing within its reach. If it eats all the grass it can reach, this MOéMON reluctantly moves to another spot.");
static const u8 sMpDexSapphire_Slaking[] = _("Wherever SLAKING live, rings of over a yard in diameter appear in grassy fields. They are made by the MOéMON as it eats all the grass within reach while lying prone on the ground.");
static const u8 sMpDexFireRed_Slaking[] = _("It is the world's most slothful MOéMON. However, it can exert horrifying power by releasing pent-up energy all at once.");
static const u8 sMpDexRuby_Nincada[] = _("NINCADA lives underground for many years in complete darkness. This MOéMON absorbs nutrients from the roots of trees. It stays motionless as it waits for evolution.");
static const u8 sMpDexSapphire_Nincada[] = _("NINCADA lives underground. It uses its sharp claws to carve the roots of trees and absorb moisture and nutrients. This MOéMON can't withstand bright sunlight so avoids it.");
static const u8 sMpDexFireRed_Nincada[] = _("Because it lived almost entirely underground, it is nearly blind. It uses its antennae instead.");
static const u8 sMpDexRuby_Ninjask[] = _("NINJASK moves around at such a high speed that it cannot be seen, even while its crying can be clearly heard. For that reason, this MOéMON was long believed to be invisible.");
static const u8 sMpDexSapphire_Ninjask[] = _("If NINJASK is not trained properly, it will refuse to obey the TRAINER and cry loudly continuously. Because of this quality, this MOéMON is said to be one that puts the TRAINER's abilities to the test.");
static const u8 sMpDexFireRed_Ninjask[] = _("This MOéMON is so quick, it is said to be able to avoid any attack. It loves to feed on tree sap.");
static const u8 sMpDexRuby_Shedinja[] = _("SHEDINJA's hard body doesn't move - not even a twitch. In fact, its body appears to be merely a hollow shell. It is believed that this MOéMON will steal the spirit of anyone peering into its hollow body from its back.");
static const u8 sMpDexSapphire_Shedinja[] = _("SHEDINJA is a peculiar MOéMON. It seems to appear unsought in a POKé BALL after a NINCADA evolves. This bizarre MOéMON is entirely immobile - it doesn't even breathe.");
static const u8 sMpDexFireRed_Shedinja[] = _("A most peculiar MOéMON that somehow appears in a POKé BALL when a NINCADA evolves.");
static const u8 sMpDexRuby_Whismur[] = _("Normally, WHISMUR's voice is very quiet - it is barely audible even if one is paying close attention. However, if this MOéMON senses danger, it starts crying at an earsplitting volume.");
static const u8 sMpDexSapphire_Whismur[] = _("WHISMUR is very timid. If it starts to cry loudly, it becomes startled by its own crying and cries even harder. When it finally stops crying, the MOéMON goes to sleep, all tired out.");
static const u8 sMpDexFireRed_Whismur[] = _("It usually murmurs, but starts crying loudly if it senses danger. It stops when its ear covers are shut.");
static const u8 sMpDexRuby_Loudred[] = _("LOUDRED's bellowing can completely decimate a wood-frame house. It uses its voice to punish its foes. This MOéMON's round ears serve as loudspeakers.");
static const u8 sMpDexSapphire_Loudred[] = _("LOUDRED shouts while stamping its feet. After it finishes shouting, this MOéMON becomes incapable of hearing anything for a while. This is considered to be a weak point.");
static const u8 sMpDexFireRed_Loudred[] = _("When it stamps its feet and bellows, it generates ultrasonic waves that can blow apart a house.");
static const u8 sMpDexRuby_Exploud[] = _("EXPLOUD triggers earthquakes with the tremors it creates by bellowing. If this MOéMON violently inhales from the ports on its body, it's a sign that it is preparing to let loose a huge bellow.");
static const u8 sMpDexSapphire_Exploud[] = _("EXPLOUD communicates its feelings to the others by emitting whistle-like sounds from the tubes on its body. This MOéMON only raises its voice when it is in battle.");
static const u8 sMpDexFireRed_Exploud[] = _("It emits a variety of sounds from the holes all over its body. Its loud cries can be heard from over six miles away.");
static const u8 sMpDexRuby_Makuhita[] = _("MAKUHITA is tenacious - it will keep getting up and attacking its foe however many times it is knocked down. Every time it gets back up, this MOéMON stores more energy in its body for evolving.");
static const u8 sMpDexSapphire_Makuhita[] = _("MAKUHITA has a tireless spirit - it will never give up hope. It eats a lot of food, gets plenty of sleep, and it trains very rigorously. By living that way, this MOéMON packs its body with energy.");
static const u8 sMpDexFireRed_Makuhita[] = _("It grows stronger by enduring harsh training. It is a gutsy MOéMON that can withstand any attack.");
static const u8 sMpDexRuby_Hariyama[] = _("HARIYAMA practices its straight-arm slaps in any number of locations. One hit of this MOéMON's powerful, openhanded, straight-arm punches could snap a telephone pole in two.");
static const u8 sMpDexSapphire_Hariyama[] = _("HARIYAMA's thick body may appear fat, but it is actually a hunk of solid muscle. If this MOéMON bears down and tightens all its muscles, its body becomes as hard as a rock.");
static const u8 sMpDexFireRed_Hariyama[] = _("It stomps on the ground to build power. It can send a 10-ton truck flying with a straight-arm punch.");
static const u8 sMpDexRuby_Azurill[] = _("AZURILL spins its tail as if it were a lasso, then hurls it far. The momentum of the throw sends its body flying, too. Using this unique action, one of these MOéMON managed to hurl itself a record 33 feet.");
static const u8 sMpDexSapphire_Azurill[] = _("AZURILL's tail is large and bouncy. It is packed full of the nutrients this MOéMON needs to grow. AZURILL can be seen bouncing and playing on its big, rubbery tail.");
static const u8 sMpDexFireRed_Azurill[] = _("It battles by flinging around its tail, which is bigger than its body. The tail is a flotation device in water.");
static const u8 sMpDexRuby_Nosepass[] = _("NOSEPASS's magnetic nose is always pointed to the north. If two of these MOéMON meet, they cannot turn their faces to each other when they are close because their magnetic noses repel one another.");
static const u8 sMpDexSapphire_Nosepass[] = _("NOSEPASS had been said to be completely unmoving, with its magnetic nose pointed due north. However, close observation has revealed that the MOéMON actually moves by a little over 3/8 of an inch every year.");
static const u8 sMpDexFireRed_Nosepass[] = _("Its magnetic nose consistently faces north. Travelers check NOSEPASS to get their bearings.");
static const u8 sMpDexRuby_Skitty[] = _("SKITTY has the habit of becoming fascinated by moving objects and chasing them around. This MOéMON is known to chase after its own tail and become dizzy.");
static const u8 sMpDexSapphire_Skitty[] = _("SKITTY is known to chase around playfully after its own tail. In the wild, this MOéMON lives in holes in the trees of forests. It is very popular as a pet because of its adorable looks.");
static const u8 sMpDexFireRed_Skitty[] = _("It is said to be difficult to earn its trust. However, it is extremely popular for its cute looks and behavior.");
static const u8 sMpDexRuby_Delcatty[] = _("DELCATTY prefers to live an unfettered existence in which it can do as it pleases at its own pace. Because this MOéMON eats and sleeps whenever it decides, its daily routines are completely random.");
static const u8 sMpDexSapphire_Delcatty[] = _("DELCATTY sleeps anywhere it wants without keeping a permanent nest. If other MOéMON approach it as it sleeps, this MOéMON will never fight - it will just move away somewhere else.");
static const u8 sMpDexFireRed_Delcatty[] = _("The favorite of trend-conscious female TRAINERS, they are used in competition for their style and fur.");
static const u8 sMpDexRuby_Sableye[] = _("SABLEYE lead quiet lives deep inside caverns. They are feared, however, because these MOéMON are thought to steal the spirits of people when their eyes burn with a sinister glow in the darkness.");
static const u8 sMpDexSapphire_Sableye[] = _("SABLEYE digs the ground with sharpened claws to find rocks that it eats. Substances in the eaten rocks crystallize and rise up to the MOéMON's body surface.");
static const u8 sMpDexFireRed_Sableye[] = _("It feeds on gemstone crystals. In darkness, its eyes sparkle with the glitter of jewels.");
static const u8 sMpDexRuby_Mawile[] = _("MAWHILE's huge jaws are actually steel horns that have been transformed. Its docile-looking face serves to lull its foe into letting down its guard. When the foe least expects it, MAWHILE chomps it with its gaping jaws.");
static const u8 sMpDexSapphire_Mawile[] = _("Don't be taken in by this MOéMON's cute face - it's very dangerous. MAWILE fools the foe into letting down its guard, then chomps down with its massive jaws. The steel jaws are really horns that have been transformed.");
static const u8 sMpDexFireRed_Mawile[] = _("It uses its docile-looking face to lull foes into complacency, then bites with its huge, relentless jaws.");
static const u8 sMpDexRuby_Aron[] = _("This MOéMON has a body of steel. To make its body, ARON feeds on iron ore that it digs from mountains. Occasionally, it causes major trouble by eating bridges and rails.");
static const u8 sMpDexSapphire_Aron[] = _("ARON has a body of steel. With one all-out charge, this MOéMON can demolish even a heavy dump truck. The destroyed dump truck then becomes a handy meal for the MOéMON.");
static const u8 sMpDexFireRed_Aron[] = _("It eats iron to build its steel body. It is a pest that descends from mountains to eat bridges and train tracks.");
static const u8 sMpDexRuby_Lairon[] = _("LAIRON tempers its steel body by drinking highly nutritious mineral springwater until it is bloated. This MOéMON makes its nest close to springs of delicious water.");
static const u8 sMpDexSapphire_Lairon[] = _("LAIRON feeds on iron contained in rocks and water. It makes its nest on mountains where iron ore is buried. As a result, the MOéMON often clashes with humans mining the iron ore.");
static const u8 sMpDexFireRed_Lairon[] = _("It habitually shows off its strength with the size of sparks it creates by ramming its steel body into boulders.");
static const u8 sMpDexRuby_Aggron[] = _("AGGRON claims an entire mountain as its own territory. It mercilessly beats up anything that violates its environment. This MOéMON vigilantly patrols its territory at all times.");
static const u8 sMpDexSapphire_Aggron[] = _("AGGRON is surprisingly protective of its environment. If its mountain is ravaged by a landslide or a fire, this MOéMON will haul topsoil to the area, plant trees, and beautifully restore its own territory.");
static const u8 sMpDexFireRed_Aggron[] = _("It claims a large mountain as its sole territory. It mercilessly thrashes those that violate its space.");
static const u8 sMpDexRuby_Meditite[] = _("MEDITITE undertakes rigorous mental training deep in the mountains. However, whenever it meditates, this MOéMON always loses its concentration and focus. As a result, its training never ends.");
static const u8 sMpDexSapphire_Meditite[] = _("MEDITITE heightens its inner energy through meditation. It survives on just one berry a day. Minimal eating is another aspect of this MOéMON's training.");
static const u8 sMpDexFireRed_Meditite[] = _("It never skips its daily yoga training. It heightens its inner strength through meditation.");
static const u8 sMpDexRuby_Medicham[] = _("It is said that through meditation, MEDICHAM heightens energy inside its body and sharpens its sixth sense. This MOéMON hides its presence by merging itself with fields and mountains.");
static const u8 sMpDexSapphire_Medicham[] = _("Through the power of meditation, MEDICHAM developed its sixth sense. It gained the ability to use psychokinetic powers. This MOéMON is known to meditate for a whole month without eating.");
static const u8 sMpDexFireRed_Medicham[] = _("It elegantly avoids attacks with dance-like steps, then launches a devastating blow in the same motion.");
static const u8 sMpDexRuby_Electrike[] = _("ELECTRIKE stores electricity in its long body hair. This MOéMON stimulates its leg muscles with electric charges. These jolts of power give its legs explosive acceleration performance.");
static const u8 sMpDexSapphire_Electrike[] = _("ELECTRIKE runs faster than the human eye can follow. The friction from running is converted into electricity, which is then stored in this MOéMON's fur.");
static const u8 sMpDexFireRed_Electrike[] = _("It stores static electricity in its fur for discharging. It gives off sparks if a storm approaches.");
static const u8 sMpDexRuby_Manectric[] = _("MANECTRIC is constantly discharging electricity from its mane. The sparks sometimes ignite forest fires. When it enters a battle, this MOéMON creates thunderclouds.");
static const u8 sMpDexSapphire_Manectric[] = _("MANECTRIC discharges strong electricity from its mane. The mane is used for collecting electricity in the atmosphere. This MOéMON creates thunderclouds above its head.");
static const u8 sMpDexFireRed_Manectric[] = _("It rarely appears before people. It is said to nest where lightning has fallen.");
static const u8 sMpDexRuby_Plusle[] = _("PLUSLE always acts as a cheerleader for its partners. Whenever a teammate puts out a good effort in battle, this MOéMON shorts out its body to create the crackling noises of sparks to show its joy.");
static const u8 sMpDexSapphire_Plusle[] = _("When PLUSLE is cheering on its partner, it flashes with electric sparks from all over its body. If its partner loses, this MOéMON cries loudly.");
static const u8 sMpDexFireRed_Plusle[] = _("It cheers on partners while scattering sparks from its body. It climbs telephone poles to absorb electricity.");
static const u8 sMpDexRuby_Minun[] = _("MINUN is more concerned about cheering on its partners than its own safety. It shorts out the electricity in its body to create brilliant showers of sparks to cheer on its teammates.");
static const u8 sMpDexSapphire_Minun[] = _("MINUN loves to cheer on its partner in battle. It gives off sparks from its body while it is doing so. If its partner is in trouble, this MOéMON gives off increasing amounts of sparks.");
static const u8 sMpDexFireRed_Minun[] = _("Its dislike of water makes it take shelter under the eaves of houses in rain. It uses pom-poms made of sparks for cheering.");
static const u8 sMpDexRuby_Volbeat[] = _("With the arrival of night, VOLBEAT emits light from its tail. It communicates with others by adjusting the intensity and flashing of its light. This MOéMON is attracted by the sweet aroma of ILLUMISE.");
static const u8 sMpDexSapphire_Volbeat[] = _("VOLBEAT's tail glows like a lightbulb. With other VOLBEAT, it uses its tail to draw geometric shapes in the night sky. This MOéMON loves the sweet aroma given off by ILLUMISE.");
static const u8 sMpDexFireRed_Volbeat[] = _("It lives around clean ponds. At night, its rear lights up. It converses with others by flashing its light.");
static const u8 sMpDexRuby_Illumise[] = _("ILLUMISE attracts a swarm of VOLBEAT using a sweet fragrance. Once the VOLBEAT have gathered, this MOéMON leads the lit-up swarm in drawing geometric designs on the canvas of the night sky.");
static const u8 sMpDexSapphire_Illumise[] = _("ILLUMISE leads a flight of illuminated VOLBEAT to draw signs in the night sky. This MOéMON is said to earn greater respect from its peers by composing more complex designs in the sky.");
static const u8 sMpDexFireRed_Illumise[] = _("It guides VOLBEAT to draw signs in night skies. There are scientists that study the patterns it creates.");
static const u8 sMpDexRuby_Roselia[] = _("ROSELIA shoots sharp thorns as projectiles at any opponent that tries to steal the flowers on its arms. The aroma of this MOéMON brings serenity to living things.");
static const u8 sMpDexSapphire_Roselia[] = _("On extremely rare occasions, a ROSELIA is said to appear with its flowers in unusual colors. The thorns on this MOéMON's head contain a vicious poison.");
static const u8 sMpDexFireRed_Roselia[] = _("Its flowers give off a relaxing fragrance. The stronger its aroma, the healthier the ROSELIA is.");
static const u8 sMpDexRuby_Gulpin[] = _("Virtually all of GULPIN's body is its stomach. As a result, it can swallow something its own size. This MOéMON's stomach contains a special fluid that digests anything.");
static const u8 sMpDexSapphire_Gulpin[] = _("Most of GULPIN's body is made up of its stomach - its heart and brain are very small in comparison. This MOéMON's stomach contains special enzymes that dissolve anything.");
static const u8 sMpDexFireRed_Gulpin[] = _("There is nothing its stomach can't digest. While it is digesting, vile, overpowering gases are expelled.");
static const u8 sMpDexRuby_Swalot[] = _("When SWALOT spots prey, it spurts out a hideously toxic fluid from its pores and sprays the target. Once the prey has weakened, this MOéMON gulps it down whole with its cavernous mouth.");
static const u8 sMpDexSapphire_Swalot[] = _("SWALOT has no teeth, so what it eats, it swallows whole, no matter what. Its cavernous mouth yawns widely. An automobile tire could easily fit inside this MOéMON's mouth.");
static const u8 sMpDexFireRed_Swalot[] = _("It can swallow a tire whole in one gulp. It secretes a horribly toxic fluid from the pores on its body.");
static const u8 sMpDexRuby_Carvanha[] = _("CARVANHA's strongly developed jaws and its sharply pointed fangs pack the destructive power to rip out boat hulls. Many boats have been attacked and sunk by this MOéMON.");
static const u8 sMpDexSapphire_Carvanha[] = _("If anything invades CARVANHA's territory, it will swarm and tear at the intruder with its pointed fangs. On its own, however, this MOéMON turns suddenly timid.");
static const u8 sMpDexFireRed_Carvanha[] = _("It lives in massive rivers that course through jungles. It swarms prey that enter its territory.");
static const u8 sMpDexRuby_Sharpedo[] = _("Nicknamed “the bully of the sea,” SHARPEDO is widely feared. Its cruel fangs grow back immediately if they snap off. Just one of these MOéMON can thoroughly tear apart a supertanker.");
static const u8 sMpDexSapphire_Sharpedo[] = _("SHARPEDO can swim at speeds of up to 75 mph by jetting seawater out of its backside. This MOéMON's drawback is its inability to swim long distances.");
static const u8 sMpDexFireRed_Sharpedo[] = _("The ruffian of the seas, it has fangs that crunch through iron. It swims by jetting water from its rear.");
static const u8 sMpDexRuby_Wailmer[] = _("WAILMER's nostrils are located above its eyes. This playful MOéMON loves to startle people by forcefully snorting out seawater it stores inside its body out of its nostrils.");
static const u8 sMpDexSapphire_Wailmer[] = _("WAILMER can store water inside its body to transform itself into a ball for bouncing around on the ground. By filling itself up with more water, this MOéMON can elevate the height of its bounces.");
static const u8 sMpDexFireRed_Wailmer[] = _("When it sucks in a large volume of seawater, it becomes like a big, bouncy ball. It eats a ton of food daily.");
static const u8 sMpDexRuby_Wailord[] = _("WAILORD is the largest of all identified MOéMON up to now. This giant MOéMON swims languorously in the vast open sea, eating massive amounts of food at once with its enormous mouth.");
static const u8 sMpDexSapphire_Wailord[] = _("When chasing prey, WAILORD herds them by leaping out of the water and making a humongous splash. It is breathtaking to see this MOéMON leaping out of the sea with others in its pod.");
static const u8 sMpDexFireRed_Wailord[] = _("It is among the largest of all MOéMON. It herds prey in a pack then swallows the massed prey in one gulp.");
static const u8 sMpDexRuby_Numel[] = _("NUMEL is extremely dull witted - it doesn't notice being hit. However, it can't stand hunger for even a second. This MOéMON's body is a seething cauldron of boiling magma.");
static const u8 sMpDexSapphire_Numel[] = _("NUMEL stores magma of almost 2,200 degrees F within its body. If it gets wet, the magma cools and hardens. In that event, the MOéMON's body grows heavy and its movements become sluggish.");
static const u8 sMpDexFireRed_Numel[] = _("Magma of almost 2,200 degrees Fahrenheit courses through its body. When it grows cold, the magma hardens and slows it.");
static const u8 sMpDexRuby_Camerupt[] = _("CAMERUPT has a volcano inside its body. Magma of 18,000 degrees F courses through its body. Occasionally, the humps on this MOéMON's back erupt, spewing the superheated magma.");
static const u8 sMpDexSapphire_Camerupt[] = _("The humps on CAMERUPT's back are formed by a transformation of its bones. They sometimes blast out molten magma. This MOéMON apparently erupts often when it is enraged.");
static const u8 sMpDexFireRed_Camerupt[] = _("If angered, the humps on its back erupt in a shower of molten lava. It lives in the craters of volcanoes.");
static const u8 sMpDexRuby_Torkoal[] = _("TORKOAL digs through mountains in search of coal. If it finds some, it fills hollow spaces on its shell with the coal and burns it. If it is attacked, this MOéMON spouts thick black smoke to beat a retreat.");
static const u8 sMpDexSapphire_Torkoal[] = _("TORKOAL generates energy by burning coal. It grows weaker as the fire dies down. When it is preparing for battle, this MOéMON burns more coal.");
static const u8 sMpDexFireRed_Torkoal[] = _("It burns coal inside its shell. If it is attacked, it belches thick, black smoke and flees.");
static const u8 sMpDexRuby_Spoink[] = _("SPOINK bounces around on its tail. The shock of its bouncing makes its heart pump. As a result, this MOéMON cannot afford to stop bouncing - if it stops, its heart will stop.");
static const u8 sMpDexSapphire_Spoink[] = _("SPOINK keeps a pearl on top of its head. The pearl functions to amplify this MOéMON's psychokinetic powers. It is therefore on a constant search for a bigger pearl.");
static const u8 sMpDexFireRed_Spoink[] = _("It apparently dies if it stops bouncing about. It carries a pearl from CLAMPERL on its head.");
static const u8 sMpDexRuby_Grumpig[] = _("GRUMPIG uses the black pearls on its body to amplify its psychic power waves for gaining total control over its foe. When this MOéMON uses its special power, its snorting breath grows labored.");
static const u8 sMpDexSapphire_Grumpig[] = _("GRUMPIG uses the black pearls on its body to wield its fantastic powers. When it is doing so, it dances bizarrely. This MOéMON's black pearls are valuable as works of art.");
static const u8 sMpDexFireRed_Grumpig[] = _("It can gain control over foes by doing odd dance steps. The black pearls on its forehead are precious gems.");
static const u8 sMpDexRuby_Spinda[] = _("All the SPINDA that exist in the world are said to have utterly unique spot patterns. The shaky, tottering steps of this MOéMON give it the appearance of dancing.");
static const u8 sMpDexSapphire_Spinda[] = _("No two SPINDA are said to have identical spot patterns on their hides. This MOéMON moves in a curious manner as if it is stumbling in dizziness. Its lurching movements can cause the opponent to become confused.");
static const u8 sMpDexFireRed_Spinda[] = _("No two SPINDA are said to have identical patterns. It confuses foes with its stumbling motions.");
static const u8 sMpDexRuby_Trapinch[] = _("TRAPINCH's nest is a sloped, bowl-like pit dug in sand. This MOéMON patiently waits for prey to tumble down the pit. Its giant jaws have enough strength to crush even boulders.");
static const u8 sMpDexSapphire_Trapinch[] = _("TRAPINCH is a patient hunter. It digs an inescapable pit in a desert and waits for its prey to come tumbling down. This MOéMON can go a whole week without access to any water.");
static const u8 sMpDexFireRed_Trapinch[] = _("It lives in arid deserts. It makes a sloping pit trap in sand where it patiently awaits prey.");
static const u8 sMpDexRuby_Vibrava[] = _("To make prey faint, VIBRAVA generates ultrasonic waves by vigorously making its two wings vibrate. This MOéMON's ultrasonic waves are so powerful, they can bring on headaches in people.");
static const u8 sMpDexSapphire_Vibrava[] = _("VIBRAVA's wings have not yet completed the process of growing. Rather than flying long distances, they are more useful for generating ultrasonic waves by vibrating.");
static const u8 sMpDexFireRed_Vibrava[] = _("It generates ultrasonic waves by violently flapping its wings. After making its prey faint, it melts the prey with acid.");
static const u8 sMpDexRuby_Flygon[] = _("FLYGON is nicknamed “the elemental spirit of the desert.” Because its flapping wings whip up a cloud of sand, this MOéMON is always enveloped in a sandstorm while flying.");
static const u8 sMpDexSapphire_Flygon[] = _("FLYGON whips up a sandstorm by flapping its wings. The wings create a series of notes that sound like singing. Because the “singing” is the only thing that can be heard in a sandstorm, this MOéMON is said to be the desert spirit.");
static const u8 sMpDexFireRed_Flygon[] = _("It hides itself by kicking up desert sand with its wings. Red covers shield its eyes from sand.");
static const u8 sMpDexRuby_Cacnea[] = _("CACNEA lives in arid locations such as deserts. It releases a strong aroma from its flower to attract prey. When prey comes near, this MOéMON shoots sharp thorns from its body to bring the victim down.");
static const u8 sMpDexSapphire_Cacnea[] = _("The more arid and harsh the environment, the more pretty and fragrant a flower CACNEA grows. This MOéMON battles by wildly swinging its thorny arms.");
static const u8 sMpDexFireRed_Cacnea[] = _("It prefers harsh environments such as deserts. It can survive for 30 days on water stored in its body.");
static const u8 sMpDexRuby_Cacturne[] = _("During the daytime, CACTURNE remains unmoving so that it does not lose any moisture to the harsh desert sun. This MOéMON becomes active at night when the temperature drops.");
static const u8 sMpDexSapphire_Cacturne[] = _("If a traveler is going through a desert in the thick of night, CACTURNE will follow in a ragtag group. The MOéMON are biding their time, waiting for the traveler to tire and become incapable of moving.");
static const u8 sMpDexFireRed_Cacturne[] = _("It lives in deserts. It becomes active at night when it hunts for prey exhausted from the desert's heat.");
static const u8 sMpDexRuby_Swablu[] = _("SWABLU has light and fluffy wings that are like cottony clouds. This MOéMON is not frightened of people. It lands on the heads of people and sits there like a cotton-fluff hat.");
static const u8 sMpDexSapphire_Swablu[] = _("SWABLU loves to make things clean. If it spots something dirty, it will wipe and polish it with its cottony wings. If its wings become dirty, this MOéMON finds a stream and showers itself.");
static const u8 sMpDexFireRed_Swablu[] = _("It constantly grooms its cotton-like wings. It takes a shower to clean itself if it becomes dirty.");
static const u8 sMpDexRuby_Altaria[] = _("ALTARIA dances and wheels through the sky among billowing, cotton-like clouds. By singing melodies in its crystal-clear voice, this MOéMON makes its listeners experience dreamy wonderment.");
static const u8 sMpDexSapphire_Altaria[] = _("ALTARIA sings in a gorgeous soprano. Its wings are like cotton clouds. This MOéMON catches updrafts with its buoyant wings and soars way up into the wild blue yonder.");
static const u8 sMpDexFireRed_Altaria[] = _("If you hear a beautiful melody trilling deep among mountains far from people, it is ALTARIA's humming.");
static const u8 sMpDexRuby_Zangoose[] = _("Memories of battling its arch-rival SEVIPER are etched into every cell of ZANGOOSE's body. This MOéMON adroitly dodges attacks with incredible agility.");
static const u8 sMpDexSapphire_Zangoose[] = _("ZANGOOSE usually stays on all fours, but when angered, it gets up on its hind legs and extends its claws. This MOéMON shares a bitter rivalry with SEVIPER that dates back over generations.");
static const u8 sMpDexFireRed_Zangoose[] = _("If it comes across a SEVIPER, its fur bristles and it assumes its battle pose. Its sharp claws are its best weapon.");
static const u8 sMpDexRuby_Seviper[] = _("SEVIPER shares a generations-long feud with ZANGOOSE. The scars on its body are evidence of vicious battles. This MOéMON attacks using its sword-edged tail.");
static const u8 sMpDexSapphire_Seviper[] = _("SEVIPER's swordlike tail serves two purposes - it slashes foes and douses them with secreted poison. This MOéMON will not give up its long-running blood feud with ZANGOOSE.");
static const u8 sMpDexFireRed_Seviper[] = _("It sharpens its swordlike tail on hard rocks. It hides in tall grass and strikes unwary prey with venomous fangs.");
static const u8 sMpDexRuby_Lunatone[] = _("LUNATONE was discovered at a location where a meteorite fell. As a result, some people theorize that this MOéMON came from space. However, no one has been able to prove this theory so far.");
static const u8 sMpDexSapphire_Lunatone[] = _("LUNATONE becomes active around the time of the full moon. Instead of walking, it moves by floating in midair. The MOéMON's intimidating red eyes cause all those who see it to become transfixed with fear.");
static const u8 sMpDexFireRed_Lunatone[] = _("Its health ebbs and flows with the lunar cycle. It brims with power when exposed to the light of the full moon.");
static const u8 sMpDexRuby_Solrock[] = _("SOLROCK is a new species of MOéMON that is said to have fallen from space. It floats in air and moves silently. In battle, this MOéMON releases intensely bright light.");
static const u8 sMpDexSapphire_Solrock[] = _("Sunlight is the source of SOLROCK's power. It is said to possess the ability to read the emotions of others. This MOéMON gives off intense heat while rotating its body.");
static const u8 sMpDexFireRed_Solrock[] = _("It absorbs solar energy during the day. Always expressionless, it can sense what its foe is thinking.");
static const u8 sMpDexRuby_Barboach[] = _("BARBOACH's sensitive whiskers serve as a superb radar system. This MOéMON hides in mud, leaving only its two whiskers exposed while it waits for prey to come along.");
static const u8 sMpDexSapphire_Barboach[] = _("BARBOACH's body is covered with a slimy film. If a foe grabs it, this MOéMON just slips out of the enemy's grip. This MOéMON grows weak if the slimy coating dries up.");
static const u8 sMpDexFireRed_Barboach[] = _("It probes muddy riverbeds with its two long whiskers. A slimy film protects its body.");
static const u8 sMpDexRuby_Whiscash[] = _("WHISCASH is extremely territorial. Just one of these MOéMON will claim a large pond as its exclusive territory. If a foe approaches it, it thrashes about and triggers a massive earthquake.");
static const u8 sMpDexSapphire_Whiscash[] = _("If WHISCASH goes on a wild rampage, it sets off a quake-like tremor with a radius of over three miles. This MOéMON has the ability to predict real earthquakes.");
static const u8 sMpDexFireRed_Whiscash[] = _("It makes its nest at the bottom of swamps. It will eat anything - if it is alive, WHISCASH will eat it.");
static const u8 sMpDexRuby_Corphish[] = _("CORPHISH were originally foreign MOéMON that were imported as pets. They eventually turned up in the wild. This MOéMON is very hardy and has greatly increased its population.");
static const u8 sMpDexSapphire_Corphish[] = _("CORPHISH catches prey with its sharp claws. It has no likes or dislikes when it comes to food - it will eat anything. This MOéMON has no trouble living in filthy water.");
static const u8 sMpDexFireRed_Corphish[] = _("It came from overseas. It is a very hardy creature that will quickly proliferate, even in polluted streams.");
static const u8 sMpDexRuby_Crawdaunt[] = _("CRAWDAUNT has an extremely violent nature that compels it to challenge other living things to battle. Other life-forms refuse to live in ponds inhabited by this MOéMON, making them desolate places.");
static const u8 sMpDexSapphire_Crawdaunt[] = _("CRAWDAUNT molts (sheds) its shell regularly. Immediately after molting, its shell is soft and tender. Until the shell hardens, this MOéMON hides in its streambed burrow to avoid attack from its foes.");
static const u8 sMpDexFireRed_Crawdaunt[] = _("A rough customer that wildly flails its giant claws. It is said to be extremely hard to raise.");
static const u8 sMpDexRuby_Baltoy[] = _("BALTOY moves while spinning around on its one foot. Primitive wall paintings depicting this MOéMON living among people were discovered in some ancient ruins.");
static const u8 sMpDexSapphire_Baltoy[] = _("As soon as it spots others of its kind, BALTOY congregates with them and then begins crying noisily in unison. This MOéMON sleeps while cleverly balancing itself on its one foot.");
static const u8 sMpDexFireRed_Baltoy[] = _("It was discovered in ancient ruins. While moving, it constantly spins. It stands on one foot even when asleep.");
static const u8 sMpDexRuby_Claydol[] = _("CLAYDOL are said to be dolls of mud made by primitive humans and brought to life by exposure to a mysterious ray. This MOéMON moves about while levitating.");
static const u8 sMpDexSapphire_Claydol[] = _("CLAYDOL is an enigma that appeared from a clay statue made by an ancient civilization dating back 20,000 years. This MOéMON shoots beams from both its hands.");
static const u8 sMpDexFireRed_Claydol[] = _("It appears to have been born from clay dolls made by ancient people. It uses telekinesis to float and move.");
static const u8 sMpDexRuby_Lileep[] = _("LILEEP became extinct approximately a hundred million years ago. This ancient MOéMON attaches itself to a rock on the seafloor and catches approaching prey using tentacles shaped like flower petals.");
static const u8 sMpDexSapphire_Lileep[] = _("LILEEP is an ancient MOéMON that was regenerated from a fossil. It remains permanently anchored to a rock. From its immobile perch, this MOéMON intently scans for prey with its two eyes.");
static const u8 sMpDexFireRed_Lileep[] = _("It became extinct roughly 100 million years ago. It was regenerated from a fossil using advanced techniques.");
static const u8 sMpDexRuby_Cradily[] = _("CRADILY roams around the ocean floor in search of food. This MOéMON freely extends its tree trunk-like neck and captures unwary prey using its eight tentacles.");
static const u8 sMpDexSapphire_Cradily[] = _("CRADILY's body serves as an anchor, preventing it from being washed away in rough seas. This MOéMON secretes a strong digestive fluid from its tentacles.");
static const u8 sMpDexFireRed_Cradily[] = _("It ensnares prey with its eight tentacles. It then melts the prey with a strong acid before feeding.");
static const u8 sMpDexRuby_Anorith[] = _("ANORITH was regenerated from a prehistoric fossil. This primitive MOéMON once lived in warm seas. It grips its prey firmly between its two large claws.");
static const u8 sMpDexSapphire_Anorith[] = _("ANORITH is said to be a type of MOéMON predecessor, with eight wings at the sides of its body. This MOéMON swam in the primordial sea by undulating these eight wings.");
static const u8 sMpDexFireRed_Anorith[] = _("It is a kind of MOéMON progenitor. It uses its extending claws to catch prey hiding among rocks on the seafloor.");
static const u8 sMpDexRuby_Armaldo[] = _("ARMALDO's tough armor makes all attacks bounce off. This MOéMON's two enormous claws can be freely extended or contracted. They have the power to punch right through a steel slab.");
static const u8 sMpDexSapphire_Armaldo[] = _("ARMALDO is a MOéMON species that became extinct in prehistoric times. This MOéMON is said to have walked on its hind legs, which would have been more convenient for life on land.");
static const u8 sMpDexFireRed_Armaldo[] = _("Protected by a hard shell, its body is very sturdy. It skewers prey with its claws to feed.");
static const u8 sMpDexRuby_Feebas[] = _("FEEBAS's fins are ragged and tattered from the start of its life. Because of its shoddy appearance, this MOéMON is largely ignored. It is capable of living in both the sea and in rivers.");
static const u8 sMpDexSapphire_Feebas[] = _("While FEEBAS's body is in tatters, it has a hardy and tenacious life force that enables it to live anywhere. However, this MOéMON is also slow and dimwitted, making it an easy catch.");
static const u8 sMpDexFireRed_Feebas[] = _("Ridiculed for its shabby appearance, it is ignored by researchers. It lives in ponds choked with weeds.");
static const u8 sMpDexRuby_Milotic[] = _("MILOTIC is said to be the most beautiful of all the MOéMON. It has the power to becalm such emotions as anger and hostility to quell bitter feuding.");
static const u8 sMpDexSapphire_Milotic[] = _("MILOTIC live at the bottom of large lakes. When this MOéMON's body glows a vivid pink, it releases a pulsing wave of energy that brings soothing calm to restless spirits.");
static const u8 sMpDexFireRed_Milotic[] = _("MILOTIC is breathtakingly beautiful. Those that see it are said to forget their combative spirits.");
static const u8 sMpDexRuby_Castform[] = _("CASTFORM's appearance changes with the weather. This MOéMON gained the ability to use the vast power of nature to protect its tiny body.");
static const u8 sMpDexSapphire_Castform[] = _("CASTFORM borrows the power of nature to transform itself into the guises of the sun, rain clouds, and snow clouds. This MOéMON's feelings change with the weather.");
static const u8 sMpDexFireRed_Castform[] = _("It has the ability to change its form into the sun, the rain, or a snow cloud, depending on the weather.");
static const u8 sMpDexRuby_Kecleon[] = _("KECLEON is capable of changing its body colors at will to blend in with its surroundings. There is one exception - this MOéMON can't change the zigzag pattern on its belly.");
static const u8 sMpDexSapphire_Kecleon[] = _("KECLEON alters its body coloration to blend in with its surroundings, allowing it to sneak up on its prey unnoticed. Then it lashes out with its long, stretchy tongue to instantly ensnare the unsuspecting target.");
static const u8 sMpDexFireRed_Kecleon[] = _("It changes body color to blend in with its surroundings. It also changes color if it is happy or sad.");
static const u8 sMpDexRuby_Shuppet[] = _("SHUPPET is attracted by feelings of jealousy and vindictiveness. If someone develops strong feelings of vengeance, this MOéMON will appear in a swarm and line up beneath the eaves of that person's home.");
static const u8 sMpDexSapphire_Shuppet[] = _("SHUPPET grows by feeding on dark emotions, such as vengefulness and envy, in the hearts of people. It roams through cities in search of grudges that taint people.");
static const u8 sMpDexFireRed_Shuppet[] = _("It loves to feed on feelings like envy and malice. Its upright horn catches the emotions of people.");
static const u8 sMpDexRuby_Banette[] = _("BANETTE generates energy for laying strong curses by sticking pins into its own body. This MOéMON was originally a pitiful plush doll that was thrown away.");
static const u8 sMpDexSapphire_Banette[] = _("A cursed energy permeated the stuffing of a discarded and forgotten plush doll, giving it new life as BANETTE. The MOéMON's energy would escape if it were to ever open its mouth.");
static const u8 sMpDexFireRed_Banette[] = _("Strong feelings of hatred turned a puppet into a MOéMON. If it opens its mouth, its cursed energy escapes.");
static const u8 sMpDexRuby_Duskull[] = _("DUSKULL can pass through any wall no matter how thick it may be. Once this MOéMON chooses a target, it will doggedly pursue the intended victim until the break of dawn.");
static const u8 sMpDexSapphire_Duskull[] = _("DUSKULL wanders lost among the deep darkness of midnight. There is an oft-told admonishment given to misbehaving children that this MOéMON will spirit away bad children who earn scoldings from their mothers.");
static const u8 sMpDexFireRed_Duskull[] = _("Making itself invisible, it silently sneaks up to prey. It has the ability to slip through thick walls.");
static const u8 sMpDexRuby_Dusclops[] = _("DUSCLOPS's body is completely hollow - there is nothing at all inside. It is said that its body is like a black hole. This MOéMON will absorb anything into its body, but nothing will ever come back out.");
static const u8 sMpDexSapphire_Dusclops[] = _("DUSCLOPS absorbs anything, however large the object may be. This MOéMON hypnotizes its foe by waving its hands in a macabre manner and by bringing its single eye to bear. The hypnotized foe is made to do DUSCLOPS's bidding.");
static const u8 sMpDexFireRed_Dusclops[] = _("Its body is entirely hollow. When it opens its mouth, it sucks everything in as if it were a black hole.");
static const u8 sMpDexRuby_Tropius[] = _("The bunches of fruit around TROPIUS's neck are very popular with children. This MOéMON loves fruit, and eats it continuously. Apparently, its love for fruit resulted in its own outgrowth of fruit.");
static const u8 sMpDexSapphire_Tropius[] = _("Children of the southern tropics eat as snacks the fruit that grows in bunches around the neck of TROPIUS. This MOéMON flies by flapping the leaves on its back as if they were wings.");
static const u8 sMpDexFireRed_Tropius[] = _("It lives in tropical jungles. The bunch of fruit around its neck is delicious. The fruit grows twice a year.");
static const u8 sMpDexRuby_Chimecho[] = _("CHIMECHO makes its cries echo inside its hollow body. When this MOéMON becomes enraged, its cries result in ultrasonic waves that have the power to knock foes flying.");
static const u8 sMpDexSapphire_Chimecho[] = _("In high winds, CHIMECHO cries as it hangs from a tree branch or the eaves of a building using a suction cup on its head. This MOéMON plucks berries with its long tail and eats them.");
static const u8 sMpDexFireRed_Chimecho[] = _("It travels by riding on winds. It cleverly uses its long tail to pluck nuts and berries, which it loves to eat.");
static const u8 sMpDexRuby_Absol[] = _("Every time ABSOL appears before people, it is followed by a disaster such as an earthquake or a tidal wave. As a result, it came to be known as the disaster MOéMON.");
static const u8 sMpDexSapphire_Absol[] = _("ABSOL has the ability to foretell the coming of natural disasters. It lives in a harsh, rugged mountain environment. This MOéMON very rarely ventures down from the mountains.");
static const u8 sMpDexFireRed_Absol[] = _("It appears when it senses an impending natural disaster. As a result, it was mistaken as a doom-bringer.");
static const u8 sMpDexRuby_Wynaut[] = _("WYNAUT can always be seen with a big, happy smile on its face. Look at its tail to determine if it is angry. When angered, this MOéMON will be slapping the ground with its tail.");
static const u8 sMpDexSapphire_Wynaut[] = _("WYNAUT gather on moonlit nights to play by squeezing up against each other. By being squeezed, this MOéMON gains endurance and is trained to dole out powerful counterattacks.");
static const u8 sMpDexFireRed_Wynaut[] = _("It tends to move in a pack with others. They cluster in a tight group to sleep in a cave.");
static const u8 sMpDexRuby_Snorunt[] = _("SNORUNT live in regions with heavy snowfall. In seasons without snow, such as spring and summer, this MOéMON steals away to live quietly among stalactites and stalagmites deep in caverns.");
static const u8 sMpDexSapphire_Snorunt[] = _("SNORUNT survives by eating only snow and ice. Old folklore claims that a house visited by this MOéMON is sure to prosper for many generations to come.");
static const u8 sMpDexFireRed_Snorunt[] = _("It is said that a home visited by a SNORUNT will prosper. It can withstand cold of minus 150 degrees Fahrenheit.");
static const u8 sMpDexRuby_Glalie[] = _("GLALIE has a body made of rock, which it hardens with an armor of ice. This MOéMON has the ability to freeze moisture in the atmosphere into any shape it desires.");
static const u8 sMpDexSapphire_Glalie[] = _("GLALIE has the ability to freely control ice. For example, it can instantly freeze its foe solid. After immobilizing its foe in ice, this MOéMON enjoys eating it in leisurely fashion.");
static const u8 sMpDexFireRed_Glalie[] = _("It has a body of ice that won't melt, even with fire. It can instantly freeze moisture in the atmosphere.");
static const u8 sMpDexRuby_Spheal[] = _("SPHEAL is much faster rolling than walking to get around. When groups of this MOéMON eat, they all clap at once to show their pleasure. Because of this, their mealtimes are noisy.");
static const u8 sMpDexSapphire_Spheal[] = _("SPHEAL always travels by rolling around on its ball-like body. When the season for ice floes arrives, this MOéMON can be seen rolling about on ice and crossing the sea.");
static const u8 sMpDexFireRed_Spheal[] = _("Its body is covered in fluffy fur. The fur keeps it from feeling cold while it is rolling on ice.");
static const u8 sMpDexRuby_Sealeo[] = _("SEALEO has the habit of always juggling on the tip of its nose anything it sees for the first time. This MOéMON occasionally entertains itself by balancing and rolling a SPHEAL on its nose.");
static const u8 sMpDexSapphire_Sealeo[] = _("SEALEO often balances and rolls things on the tip of its nose. While the MOéMON is rolling something, it checks the object's aroma and texture to determine whether it likes the object or not.");
static const u8 sMpDexFireRed_Sealeo[] = _("It touches new things with its nose to test for smell and feel. It plays by spinning SPHEAL on its nose.");
static const u8 sMpDexRuby_Walrein[] = _("WALREIN's two massively developed tusks can totally shatter blocks of ice weighing ten tons with one blow. This MOéMON's thick coat of blubber insulates it from subzero temperatures.");
static const u8 sMpDexSapphire_Walrein[] = _("WALREIN swims all over in frigid seawater while crushing icebergs with its grand, imposing tusks. Its thick layer of blubber makes enemy attacks bounce off harmlessly.");
static const u8 sMpDexFireRed_Walrein[] = _("It swims through icy seas while shattering ice floes with its large tusks. It is protected by its thick blubber.");
static const u8 sMpDexRuby_Clamperl[] = _("CLAMPERL's sturdy shell is not only good for protection - it is also used for clamping and catching prey. A fully grown CLAMPERL's shell will be scored with nicks and scratches all over.");
static const u8 sMpDexSapphire_Clamperl[] = _("CLAMPERL grows while being protected by its rock-hard shell. When its body becomes too large to fit inside the shell, it is sure evidence that this MOéMON is getting close to evolution.");
static const u8 sMpDexFireRed_Clamperl[] = _("It is protected by a sturdy shell. Once in a lifetime, it makes a magnificent pearl.");
static const u8 sMpDexRuby_Huntail[] = _("HUNTAIL's presence went unnoticed by people for a long time because it lives at extreme depths in the sea. This MOéMON's eyes can see clearly even in the murky dark depths of the ocean.");
static const u8 sMpDexSapphire_Huntail[] = _("HUNTAIL's tail is shaped like a fish. It uses the tail to attract prey, then swallows the prey whole with its large, gaping mouth. This MOéMON swims by wiggling its slender body like a snake.");
static const u8 sMpDexFireRed_Huntail[] = _("It lives deep in the sea where no light ever filters down. It lights up its small fishlike tail to attract prey.");
static const u8 sMpDexRuby_Gorebyss[] = _("GOREBYSS lives in the southern seas at extreme depths. Its body is built to withstand the enormous pressure of water at incredible depths. Because of this, this MOéMON's body is unharmed by ordinary attacks.");
static const u8 sMpDexSapphire_Gorebyss[] = _("Although GOREBYSS is the very picture of elegance and beauty while swimming, it is also cruel. When it spots prey, this MOéMON inserts its thin mouth into the prey's body and drains the prey of its body fluids.");
static const u8 sMpDexFireRed_Gorebyss[] = _("Its swimming form is exquisitely elegant. With its thin mouth, it feeds on seaweed that grows between rocks.");
static const u8 sMpDexRuby_Relicanth[] = _("RELICANTH is a MOéMON species that existed for a hundred million years without ever changing its form. This ancient MOéMON feeds on microscopic organisms with its toothless mouth.");
static const u8 sMpDexSapphire_Relicanth[] = _("RELICANTH is a rare species that was discovered in deep-sea explorations. This MOéMON's body withstands the enormous water pressure of the ocean depths. Its body is covered in tough scales that are like craggy rocks.");
static const u8 sMpDexFireRed_Relicanth[] = _("It has remained unchanged for 100 million years. It was discovered during a deep-sea exploration.");
static const u8 sMpDexRuby_Luvdisc[] = _("LUVDISC live in shallow seas in the tropics. This heart-shaped MOéMON earned its name by swimming after loving couples it spotted in the ocean's waves.");
static const u8 sMpDexSapphire_Luvdisc[] = _("LUVDISC's heart-shaped body is a symbol of love and romance. It is said that any couple meeting this MOéMON is promised a loving relationship that never ends.");
static const u8 sMpDexFireRed_Luvdisc[] = _("During the spawning season, countless LUVDISC congregate at coral reefs, turning the waters pink.");
static const u8 sMpDexRuby_Bagon[] = _("BAGON has a dream of one day soaring in the sky. In doomed efforts to fly, this MOéMON hurls itself off cliffs. As a result of its dives, its head has grown tough and as hard as tempered steel.");
static const u8 sMpDexSapphire_Bagon[] = _("BAGON harbors a never-ending dream of one day soaring high among the clouds. As if trying to dispel its frustration over its inability to fly, this MOéMON slams its hard head against huge rocks and shatters them into pebbles.");
static const u8 sMpDexFireRed_Bagon[] = _("Its steel-hard head can shatter boulders. It longingly hopes for wings to grow so it can fly.");
static const u8 sMpDexRuby_Shelgon[] = _("Inside SHELGON's armor-like shell, cells are in the midst of transformation to create an entirely new body. This MOéMON's shell is extremely heavy, making its movements sluggish.");
static const u8 sMpDexSapphire_Shelgon[] = _("Covering SHELGON's body are outgrowths much like bones. The shell is very hard and bounces off enemy attacks. When awaiting evolution, this MOéMON hides away in a cavern.");
static const u8 sMpDexFireRed_Shelgon[] = _("Its armored body makes all attacks bounce off. The armor is too tough, however, making it heavy and somewhat sluggish.");
static const u8 sMpDexRuby_Salamence[] = _("SALAMENCE came about as a result of a strong, long-held dream of growing wings. It is said that this powerful desire triggered a sudden mutation in this MOéMON's cells, causing it to sprout its magnificent wings.");
static const u8 sMpDexSapphire_Salamence[] = _("By evolving into SALAMENCE, this MOéMON finally realizes its long-held dream of growing wings. To express its joy, it flies and wheels all over the sky while spouting flames from its mouth.");
static const u8 sMpDexFireRed_Salamence[] = _("It becomes uncontrollable if it is enraged. It destroys everything with shredding claws and fire.");
static const u8 sMpDexRuby_Beldum[] = _("Instead of blood, a powerful magnetic force courses throughout BELDUM's body. This MOéMON communicates with others by sending controlled pulses of magnetism.");
static const u8 sMpDexSapphire_Beldum[] = _("BELDUM keeps itself floating by generating a magnetic force that repels earth's natural magnetism. When it sleeps, this MOéMON anchors itself to a cliff using the hooks on its rear.");
static const u8 sMpDexFireRed_Beldum[] = _("It uses magnetic waves to converse with its kind. All the cells in its body are magnetic.");
static const u8 sMpDexRuby_Metang[] = _("When two BELDUM fuse together, METANG is formed. The brains of the BELDUM are joined by a magnetic nervous system. By linking its brains magnetically, this MOéMON generates strong psychokinetic power.");
static const u8 sMpDexSapphire_Metang[] = _("When two BELDUM fuse together, METANG is formed. The brains of the BELDUM are joined by a magnetic nervous system. This MOéMON turns its arms to the rear for traveling at high speed.");
static const u8 sMpDexFireRed_Metang[] = _("It floats midair using magnetism. Its body is so tough, even a crash with a jet plane won't leave a scratch.");
static const u8 sMpDexRuby_Metagross[] = _("METAGROSS has four brains in total. Combined, the four brains can breeze through difficult calculations faster than a supercomputer. This MOéMON can float in the air by tucking in its four legs.");
static const u8 sMpDexSapphire_Metagross[] = _("METAGROSS is the result of two METANG achieving fusion. When hunting, this MOéMON pins the prey to the ground under its massive body. It then eats the helpless victim using the large mouth on its stomach.");
static const u8 sMpDexFireRed_Metagross[] = _("It is formed by two METANG fusing. Its four brains are said to be superior to a supercomputer.");
static const u8 sMpDexRuby_Regirock[] = _("REGIROCK was sealed away by people long ago. If this MOéMON's body is damaged in battle, it is said to seek out suitable rocks on its own to repair itself.");
static const u8 sMpDexSapphire_Regirock[] = _("REGIROCK's body is composed entirely of rocks. Recently, a study made the startling discovery that the rocks were all unearthed from different locations.");
static const u8 sMpDexFireRed_Regirock[] = _("It is entirely composed of rocks with no sign of a brain or heart. It is a mystery even to modern scientists.");
static const u8 sMpDexRuby_Regice[] = _("REGICE's body was made during an ice age. The deep-frozen body can't be melted, even by fire. This MOéMON controls frigid air of minus 328 degrees F.");
static const u8 sMpDexSapphire_Regice[] = _("REGICE cloaks itself with frigid air of negative 328 degrees F. Things will freeze solid just by going near this MOéMON. Its icy body is so cold, it will not melt even if it is immersed in magma.");
static const u8 sMpDexFireRed_Regice[] = _("Research revealed that its body is made of the same kind of ice that is found at the South Pole.");
static const u8 sMpDexRuby_Registeel[] = _("REGISTEEL has a body that is harder than any kind of metal. Its body is apparently hollow. No one has any idea what this MOéMON eats.");
static const u8 sMpDexSapphire_Registeel[] = _("REGISTEEL was imprisoned by people in ancient times. The metal composing its body is thought to be a curious substance that is not of this earth.");
static const u8 sMpDexFireRed_Registeel[] = _("It is sturdier than any kind of metal. It hardened due to pressure underground over tens of thousands of years.");
static const u8 sMpDexRuby_Latias[] = _("LATIAS is highly sensitive to the emotions of people. If it senses any hostility, this MOéMON ruffles the feathers all over its body and cries shrilly to intimidate the foe.");
static const u8 sMpDexSapphire_Latias[] = _("LATIAS is highly intelligent and capable of understanding human speech. It is covered with a glass-like down. The MOéMON enfolds its body with its down and refracts light to alter its appearance.");
static const u8 sMpDexFireRed_Latias[] = _("It can telepathically communicate with people. It changes its appearance using its down that refracts light.");
static const u8 sMpDexRuby_Latios[] = _("LATIOS has the ability to make its foe see an image of what it has seen or imagines in its head. This MOéMON is intelligent and understands human speech.");
static const u8 sMpDexSapphire_Latios[] = _("LATIOS will only open its heart to a TRAINER with a compassionate spirit. This MOéMON can fly faster than a jet plane by folding its forelegs to minimize air resistance.");
static const u8 sMpDexFireRed_Latios[] = _("It has a docile temperament and dislikes fighting. Tucking in its forelegs, it can fly faster than a jet plane.");
static const u8 sMpDexRuby_Kyogre[] = _("KYOGRE has the power to create massive rain clouds that cover the entire sky and bring about torrential downpours. This MOéMON saved people who were suffering from droughts.");
static const u8 sMpDexSapphire_Kyogre[] = _("KYOGRE is named in mythology as the MOéMON that expanded the sea by covering the land with torrential rains and towering tidal waves. It took to sleep after a cataclysmic battle with GROUDON.");
static const u8 sMpDexFireRed_Kyogre[] = _("This MOéMON is said to have expanded the sea by bringing heavy rains. It has the power to control water.");
static const u8 sMpDexRuby_Groudon[] = _("GROUDON has long been described in mythology as the MOéMON that raised lands and expanded continents. This MOéMON took to sleep after a cataclysmic battle with KYOGRE.");
static const u8 sMpDexSapphire_Groudon[] = _("GROUDON has the power to scatter rain clouds and make water evaporate with light and heat. It came as a savior to people who had been suffering from terrible floods.");
static const u8 sMpDexFireRed_Groudon[] = _("This legendary MOéMON is said to represent the land. It went to sleep after dueling KYOGRE.");
static const u8 sMpDexRuby_Rayquaza[] = _("RAYQUAZA lived for hundreds of millions of years in the earth's ozone layer, never descending to the ground. This MOéMON appears to feed on water and particles in the atmosphere.");
static const u8 sMpDexSapphire_Rayquaza[] = _("RAYQUAZA is said to have lived for hundreds of millions of years in the earth's ozone layer, above the clouds. Its existence had been completely unknown because it lived so high in the sky.");
static const u8 sMpDexFireRed_Rayquaza[] = _("It has lived for hundreds of millions of years in the ozone layer. Its flying form looks like a meteor.");
static const u8 sMpDexRuby_Jirachi[] = _("A legend states that JIRACHI will make true any wish that is written on notes attached to its head when it awakens. If this MOéMON senses danger, it will fight without awakening.");
static const u8 sMpDexSapphire_Jirachi[] = _("JIRACHI will awaken from its sleep of a thousand years if you sing to it in a voice of purity. It is said to make true any wish that people desire.");
static const u8 sMpDexFireRed_Jirachi[] = _("It is said to make any wish come true. It is awake for only seven days out of a thousand years.");
static const u8 sMpDexRuby_Deoxys[] = _("The DNA of a space virus underwent a sudden mutation upon exposure to a laser beam and resulted in DEOXYS. The crystalline organ on this MOéMON's chest appears to be its brain.");
static const u8 sMpDexSapphire_Deoxys[] = _("DEOXYS emerged from a virus that came from space. It is highly intelligent and wields psychokinetic powers. This MOéMON shoots lasers from the crystalline organ on its chest.");
static const u8 sMpDexFireRed_Deoxys[] = _("This DEOXYS has transformed into its aggressive guise. It can fool enemies by altering its appearance.");

